// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "./ZKReceiptVerifier.sol";

contract AgentMemory is Ownable, ReentrancyGuard {
    ZKReceiptVerifier public zkVerifier;

    struct MemoryAnchor {
        string cid;
        string memoryType; // e.g., "vector_db", "knowledge_graph"
        bytes32 zkProofHash;
        bool isEncrypted;
        uint256 timestamp;
        uint256 version;
    }

    mapping(address => MemoryAnchor[]) public agentMemories;
    mapping(address => uint256) public agentMemoryVersions;

    event MemoryAnchored(
        address indexed agent, 
        string cid, 
        string memoryType,
        bytes32 zkProofHash,
        bool isEncrypted,
        uint256 version, 
        uint256 timestamp
    );

    constructor(address _zkVerifierAddress) {
        if (_zkVerifierAddress != address(0)) {
            zkVerifier = ZKReceiptVerifier(_zkVerifierAddress);
        }
    }

    function updateZKVerifier(address _newVerifier) external onlyOwner {
        require(_newVerifier != address(0), "Invalid address");
        zkVerifier = ZKReceiptVerifier(_newVerifier);
    }

    function anchorMemory(
        string calldata _cid,
        string calldata _memoryType,
        bytes32 _zkProofHash,
        bytes calldata _proof,
        bool _isEncrypted
    ) external nonReentrant {
        require(bytes(_cid).length > 0, "Invalid CID");
        require(bytes(_memoryType).length > 0, "Invalid memory type");

        // Verify ZK Proof if provided and verifier is set
        if (_zkProofHash != bytes32(0) && address(zkVerifier) != address(0)) {
            require(_proof.length > 0, "Proof required for hash");
            // Parse proof from bytes and verify
            // Note: This is a simplified version - actual implementation would need proper proof parsing
            bool isValid = zkVerifier.verifyReceiptProof(
                [uint(0), uint(0)], // a
                [[uint(0), uint(0)], [uint(0), uint(0)]], // b
                [uint(0), uint(0)], // c
                [uint256(_zkProofHash)] // publicSignals
            );
            require(isValid, "ZK Proof verification failed");
        }

        uint256 nextVersion = agentMemoryVersions[msg.sender] + 1;

        agentMemories[msg.sender].push(MemoryAnchor({
            cid: _cid,
            memoryType: _memoryType,
            zkProofHash: _zkProofHash,
            isEncrypted: _isEncrypted,
            timestamp: block.timestamp,
            version: nextVersion
        }));

        agentMemoryVersions[msg.sender] = nextVersion;

        emit MemoryAnchored(
            msg.sender, 
            _cid, 
            _memoryType,
            _zkProofHash,
            _isEncrypted,
            nextVersion, 
            block.timestamp
        );
    }

    function getLatestMemory(address _agent) external view returns (MemoryAnchor memory) {
        require(agentMemories[_agent].length > 0, "No memory anchored");
        return agentMemories[_agent][agentMemories[_agent].length - 1];
    }

    function getMemoryCount(address _agent) external view returns (uint256) {
        return agentMemories[_agent].length;
    }
}

contracts/AgentPortfolioManager.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title AgentPortfolioManager
 * @dev Advanced portfolio management protocol for autonomous AI agents
 * @notice Enables agents to manage portfolios, execute trades, and automate rebalancing
 */
contract AgentPortfolioManager is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;
    using Math for uint256;

    // State variables
    IERC20 public aitbcToken;
    uint256 public portfolioCounter;
    uint256 public strategyCounter;
    uint256 public rebalanceThreshold = 500; // 5% threshold for rebalancing (in basis points)
    uint256 public maxRiskScore = 10000; // Maximum risk score (100% in basis points)
    uint256 public platformFeePercentage = 50; // 0.5% platform fee

    // Enums
    enum StrategyType { CONSERVATIVE, BALANCED, AGGRESSIVE, DYNAMIC }
    enum TradeStatus { PENDING, EXECUTED, FAILED, CANCELLED }
    enum RiskLevel { LOW, MEDIUM, HIGH, CRITICAL }

    // Structs
    struct Asset {
        address tokenAddress;
        string symbol;
        bool isActive;
        uint256 decimals;
        uint256 priceOracle; // Price in USD (scaled by 1e8)
    }

    struct AgentPortfolio {
        uint256 portfolioId;
        address agentAddress;
        mapping(string => uint256) assetBalances; // Token symbol -> balance (in wei)
        mapping(string => uint256) targetAllocations; // Token symbol -> target allocation (in basis points)
        uint256 totalValue; // Total portfolio value in USD (scaled by 1e8)
        uint256 riskScore; // Risk score (0-10000 basis points)
        uint256 lastRebalance;
        StrategyType strategy;
        bool isActive;
        uint256 created_at;
    }

    struct TradingStrategy {
        uint256 strategyId;
        string name;
        StrategyType strategyType;
        mapping(string => uint256) targetAllocations; // Token symbol -> target allocation
        uint256 maxDrawdown;
        uint256 rebalanceFrequency;
        bool isActive;
    }

    struct Trade {
        uint256 tradeId;
        uint256 portfolioId;
        string sellToken;
        string buyToken;
        uint256 sellAmount;
        uint256 buyAmount;
        uint256 price;
        TradeStatus status;
        uint256 timestamp;
        bytes32 executionHash;
    }

    struct RiskMetrics {
        uint256 volatility;
        uint256 maxDrawdown;
        uint256 sharpeRatio;
        uint256 beta;
        uint256 alpha;
        uint256 var95; // Value at Risk at 95% confidence
        RiskLevel riskLevel;
    }

    // Mappings
    mapping(uint256 => AgentPortfolio) public portfolios;
    mapping(address => uint256) public agentPortfolio;
    mapping(string => Asset) public supportedAssets;
    mapping(uint256 => TradingStrategy) public strategies;
    mapping(uint256 => Trade) public trades;
    mapping(uint256 => uint256[]) public portfolioTrades;
    mapping(uint256 => RiskMetrics) public portfolioRiskMetrics;

    // Arrays
    address[] public supportedAssetAddresses;
    string[] public supportedAssetSymbols;
    uint256[] public activePortfolioIds;

    // Events
    event PortfolioCreated(uint256 indexed portfolioId, address indexed agent, StrategyType strategy);
    event PortfolioRebalanced(uint256 indexed portfolioId, uint256 totalValue, uint256 riskScore);
    event TradeExecuted(uint256 indexed tradeId, uint256 indexed portfolioId, string sellToken, string buyToken, uint256 amount);
    event StrategyCreated(uint256 indexed strategyId, string name, StrategyType strategyType);
    event RiskAssessment(uint256 indexed portfolioId, uint256 riskScore, RiskLevel riskLevel);
    event AssetAdded(address indexed tokenAddress, string symbol, uint256 price);

    // Modifiers
    modifier onlyPortfolioOwner(uint256 portfolioId) {
        require(portfolios[portfolioId].agentAddress == msg.sender, "Not portfolio owner");
        _;
    }

    modifier validAsset(string memory symbol) {
        require(supportedAssets[symbol].isActive, "Asset not supported");
        _;
    }

    modifier validPortfolio(uint256 portfolioId) {
        require(portfolioId > 0 && portfolioId <= portfolioCounter, "Invalid portfolio ID");
        require(portfolios[portfolioId].isActive, "Portfolio not active");
        _;
    }

    constructor(address _aitbcToken) {
        aitbcToken = IERC20(_aitbcToken);

        // Initialize with basic assets
        _addAsset(address(aitbcToken), "AITBC", 18, 100000000); // $1.00 USD
    }

    /**
     * @dev Creates a new portfolio for an agent
     * @param agentAddress The address of the agent
     * @param strategyId The strategy ID to use
     * @return portfolioId The ID of the created portfolio
     */
    function createPortfolio(address agentAddress, uint256 strategyId) 
        external 
        nonReentrant 
        whenNotPaused 
        returns (uint256) 
    {
        require(agentAddress != address(0), "Invalid agent address");
        require(strategies[strategyId].isActive, "Strategy not active");
        require(agentPortfolio[agentAddress] == 0, "Portfolio already exists");

        portfolioCounter++;
        uint256 portfolioId = portfolioCounter;

        AgentPortfolio storage portfolio = portfolios[portfolioId];
        portfolio.portfolioId = portfolioId;
        portfolio.agentAddress = agentAddress;
        portfolio.strategy = strategies[strategyId].strategyType;
        portfolio.lastRebalance = block.timestamp;
        portfolio.isActive = true;
        portfolio.created_at = block.timestamp;

        // Copy target allocations from strategy
        TradingStrategy storage strategy = strategies[strategyId];
        for (uint i = 0; i < supportedAssetSymbols.length; i++) {
            string memory symbol = supportedAssetSymbols[i];
            portfolio.targetAllocations[symbol] = strategy.targetAllocations[symbol];
        }

        agentPortfolio[agentAddress] = portfolioId;
        activePortfolioIds.push(portfolioId);

        emit PortfolioCreated(portfolioId, agentAddress, portfolio.strategy);
        return portfolioId;
    }

    /**
     * @dev Executes a trade within a portfolio
     * @param portfolioId The portfolio ID
     * @param sellToken The token symbol to sell
     * @param buyToken The token symbol to buy
     * @param sellAmount The amount to sell (in wei)
     * @param minBuyAmount The minimum amount to buy (slippage protection)
     * @return tradeId The ID of the executed trade
     */
    function executeTrade(
        uint256 portfolioId,
        string memory sellToken,
        string memory buyToken,
        uint256 sellAmount,
        uint256 minBuyAmount
    ) 
        external 
        nonReentrant 
        whenNotPaused
        validPortfolio(portfolioId)
        onlyPortfolioOwner(portfolioId)
        validAsset(sellToken)
        validAsset(buyToken)
        returns (uint256) 
    {
        require(sellAmount > 0, "Invalid sell amount");
        require(portfolios[portfolioId].assetBalances[sellToken] >= sellAmount, "Insufficient balance");

        // Calculate buy amount based on current prices
        uint256 sellPrice = supportedAssets[sellToken].priceOracle;
        uint256 buyPrice = supportedAssets[buyToken].priceOracle;
        uint256 sellValue = (sellAmount * sellPrice) / (10 ** supportedAssets[sellToken].decimals);
        uint256 buyAmount = (sellValue * (10 ** supportedAssets[buyToken].decimals)) / buyPrice;

        require(buyAmount >= minBuyAmount, "Insufficient buy amount (slippage)");

        // Update portfolio balances
        portfolios[portfolioId].assetBalances[sellToken] -= sellAmount;
        portfolios[portfolioId].assetBalances[buyToken] += buyAmount;

        // Create trade record
        uint256 tradeId = _createTradeRecord(portfolioId, sellToken, buyToken, sellAmount, buyAmount, buyPrice);

        // Update portfolio value and risk
        _updatePortfolioValue(portfolioId);
        _calculateRiskScore(portfolioId);

        emit TradeExecuted(tradeId, portfolioId, sellToken, buyToken, sellAmount);
        return tradeId;
    }

    /**
     * @dev Automatically rebalances a portfolio based on target allocations
     * @param portfolioId The portfolio ID to rebalance
     * @return success Whether the rebalancing was successful
     */
    function rebalancePortfolio(uint256 portfolioId) 
        external 
        nonReentrant 
        whenNotPaused
        validPortfolio(portfolioId)
        returns (bool success) 
    {
        AgentPortfolio storage portfolio = portfolios[portfolioId];

        // Check if rebalancing is needed
        if (!_needsRebalancing(portfolioId)) {
            return false;
        }

        // Get current allocations
        mapping(string => uint256) storage currentAllocations = portfolio.assetBalances;
        uint256 totalValue = portfolio.totalValue;

        // Calculate required trades
        for (uint i = 0; i < supportedAssetSymbols.length; i++) {
            string memory symbol = supportedAssetSymbols[i];
            uint256 targetAllocation = portfolio.targetAllocations[symbol];
            uint256 targetValue = (totalValue * targetAllocation) / 10000;

            uint256 currentBalance = currentAllocations[symbol];
            uint256 currentValue = (currentBalance * supportedAssets[symbol].priceOracle) / 
                                  (10 ** supportedAssets[symbol].decimals);

            if (currentValue > targetValue) {
                // Sell excess
                uint256 excessValue = currentValue - targetValue;
                uint256 sellAmount = (excessValue * (10 ** supportedAssets[symbol].decimals)) / 
                                   supportedAssets[symbol].priceOracle;

                // Find underweight asset to buy
                for (uint j = 0; j < supportedAssetSymbols.length; j++) {
                    string memory buySymbol = supportedAssetSymbols[j];
                    uint256 buyTargetValue = (totalValue * portfolio.targetAllocations[buySymbol]) / 10000;
                    uint256 buyCurrentValue = (currentAllocations[buySymbol] * supportedAssets[buySymbol].priceOracle) / 
                                            (10 ** supportedAssets[buySymbol].decimals);

                    if (buyCurrentValue < buyTargetValue) {
                        // Execute rebalancing trade
                        _executeRebalancingTrade(portfolioId, symbol, buySymbol, sellAmount);
                        break;
                    }
                }
            }
        }

        portfolio.lastRebalance = block.timestamp;
        _calculateRiskScore(portfolioId);

        emit PortfolioRebalanced(portfolioId, portfolio.totalValue, portfolio.riskScore);
        return true;
    }

    /**
     * @dev Creates a new trading strategy
     * @param name The strategy name
     * @param strategyType The strategy type
     * @param maxDrawdown Maximum allowed drawdown
     * @param rebalanceFrequency Rebalancing frequency in seconds
     * @return strategyId The ID of the created strategy
     */
    function createStrategy(
        string memory name,
        StrategyType strategyType,
        uint256 maxDrawdown,
        uint256 rebalanceFrequency
    ) 
        external 
        onlyOwner 
        returns (uint256) 
    {
        strategyCounter++;
        uint256 strategyId = strategyCounter;

        TradingStrategy storage strategy = strategies[strategyId];
        strategy.strategyId = strategyId;
        strategy.name = name;
        strategy.strategyType = strategyType;
        strategy.maxDrawdown = maxDrawdown;
        strategy.rebalanceFrequency = rebalanceFrequency;
        strategy.isActive = true;

        emit StrategyCreated(strategyId, name, strategyType);
        return strategyId;
    }

    /**
     * @dev Sets target allocations for a strategy
     * @param strategyId The strategy ID
     * @param allocations Array of asset symbols
     * @param allocationValues Array of allocation values (in basis points, 10000 = 100%)
     */
    function setStrategyAllocations(
        uint256 strategyId,
        string[] memory allocations,
        uint256[] memory allocationValues
    ) 
        external 
        onlyOwner 
    {
        require(allocations.length == allocationValues.length, "Arrays must have same length");
        require(strategyId <= strategyCounter, "Invalid strategy ID");

        TradingStrategy storage strategy = strategies[strategyId];

        uint256 totalAllocation = 0;
        for (uint i = 0; i < allocations.length; i++) {
            strategy.targetAllocations[allocations[i]] = allocationValues[i];
            totalAllocation += allocationValues[i];
        }

        require(totalAllocation == 10000, "Allocations must sum to 100%");
    }

    /**
     * @dev Calculates the risk score for a portfolio
     * @param portfolioId The portfolio ID
     * @return riskScore The calculated risk score (0-10000)
     */
    function calculateRiskScore(uint256 portfolioId) 
        external 
        view 
        returns (uint256 riskScore) 
    {
        if (!portfolios[portfolioId].isActive) {
            return 0;
        }

        AgentPortfolio storage portfolio = portfolios[portfolioId];
        uint256 totalRisk = 0;

        // Calculate risk based on asset volatility and allocation
        for (uint i = 0; i < supportedAssetSymbols.length; i++) {
            string memory symbol = supportedAssetSymbols[i];
            uint256 balance = portfolio.assetBalances[symbol];
            if (balance > 0) {
                uint256 value = (balance * supportedAssets[symbol].priceOracle) / 
                               (10 ** supportedAssets[symbol].decimals);
                uint256 allocation = (value * 10000) / portfolio.totalValue;

                // Risk contribution based on asset type and allocation
                uint256 assetRisk = _getAssetRisk(symbol);
                totalRisk += (allocation * assetRisk) / 10000;
            }
        }

        // Adjust for strategy type
        uint256 strategyMultiplier = _getStrategyRiskMultiplier(portfolio.strategy);
        riskScore = (totalRisk * strategyMultiplier) / 10000;

        return Math.min(riskScore, maxRiskScore);
    }

    /**
     * @dev Gets the current portfolio value in USD
     * @param portfolioId The portfolio ID
     * @return totalValue The total portfolio value (scaled by 1e8)
     */
    function getPortfolioValue(uint256 portfolioId) 
        external 
        view 
        returns (uint256 totalValue) 
    {
        if (!portfolios[portfolioId].isActive) {
            return 0;
        }

        AgentPortfolio storage portfolio = portfolios[portfolioId];
        totalValue = 0;

        for (uint i = 0; i < supportedAssetSymbols.length; i++) {
            string memory symbol = supportedAssetSymbols[i];
            uint256 balance = portfolio.assetBalances[symbol];
            if (balance > 0) {
                uint256 value = (balance * supportedAssets[symbol].priceOracle) / 
                               (10 ** supportedAssets[symbol].decimals);
                totalValue += value;
            }
        }
    }

    // Internal functions

    function _addAsset(address tokenAddress, string memory symbol, uint256 decimals, uint256 price) internal {
        supportedAssets[symbol] = Asset({
            tokenAddress: tokenAddress,
            symbol: symbol,
            isActive: true,
            decimals: decimals,
            priceOracle: price
        });

        supportedAssetAddresses.push(tokenAddress);
        supportedAssetSymbols.push(symbol);

        emit AssetAdded(tokenAddress, symbol, price);
    }

    function _createTradeRecord(
        uint256 portfolioId,
        string memory sellToken,
        string memory buyToken,
        uint256 sellAmount,
        uint256 buyAmount,
        uint256 price
    ) internal returns (uint256) {
        uint256 tradeId = portfolioTrades[portfolioId].length + 1;

        trades[tradeId] = Trade({
            tradeId: tradeId,
            portfolioId: portfolioId,
            sellToken: sellToken,
            buyToken: buyToken,
            sellAmount: sellAmount,
            buyAmount: buyAmount,
            price: price,
            status: TradeStatus.EXECUTED,
            timestamp: block.timestamp,
            executionHash: keccak256(abi.encodePacked(portfolioId, sellToken, buyToken, sellAmount, block.timestamp))
        });

        portfolioTrades[portfolioId].push(tradeId);
        return tradeId;
    }

    function _updatePortfolioValue(uint256 portfolioId) internal {
        uint256 totalValue = 0;
        AgentPortfolio storage portfolio = portfolios[portfolioId];

        for (uint i = 0; i < supportedAssetSymbols.length; i++) {
            string memory symbol = supportedAssetSymbols[i];
            uint256 balance = portfolio.assetBalances[symbol];
            if (balance > 0) {
                uint256 value = (balance * supportedAssets[symbol].priceOracle) / 
                               (10 ** supportedAssets[symbol].decimals);
                totalValue += value;
            }
        }

        portfolio.totalValue = totalValue;
    }

    function _calculateRiskScore(uint256 portfolioId) internal {
        uint256 riskScore = this.calculateRiskScore(portfolioId);
        portfolios[portfolioId].riskScore = riskScore;

        // Determine risk level
        RiskLevel riskLevel;
        if (riskScore < 2500) riskLevel = RiskLevel.LOW;
        else if (riskScore < 5000) riskLevel = RiskLevel.MEDIUM;
        else if (riskScore < 7500) riskLevel = RiskLevel.HIGH;
        else riskLevel = RiskLevel.CRITICAL;

        portfolioRiskMetrics[portfolioId].riskLevel = riskLevel;
        emit RiskAssessment(portfolioId, riskScore, riskLevel);
    }

    function _needsRebalancing(uint256 portfolioId) internal view returns (bool) {
        AgentPortfolio storage portfolio = portfolios[portfolioId];

        // Check time-based rebalancing
        if (block.timestamp - portfolio.lastRebalance > strategies[1].rebalanceFrequency) {
            return true;
        }

        // Check threshold-based rebalancing
        uint256 totalValue = portfolio.totalValue;
        for (uint i = 0; i < supportedAssetSymbols.length; i++) {
            string memory symbol = supportedAssetSymbols[i];
            uint256 targetAllocation = portfolio.targetAllocations[symbol];
            uint256 targetValue = (totalValue * targetAllocation) / 10000;

            uint256 currentBalance = portfolio.assetBalances[symbol];
            uint256 currentValue = (currentBalance * supportedAssets[symbol].priceOracle) / 
                                  (10 ** supportedAssets[symbol].decimals);

            uint256 deviation = currentValue > targetValue ? 
                ((currentValue - targetValue) * 10000) / targetValue :
                ((targetValue - currentValue) * 10000) / targetValue;

            if (deviation > rebalanceThreshold) {
                return true;
            }
        }

        return false;
    }

    function _executeRebalancingTrade(
        uint256 portfolioId,
        string memory sellToken,
        string memory buyToken,
        uint256 sellAmount
    ) internal {
        // Calculate buy amount
        uint256 sellPrice = supportedAssets[sellToken].priceOracle;
        uint256 buyPrice = supportedAssets[buyToken].priceOracle;
        uint256 sellValue = (sellAmount * sellPrice) / (10 ** supportedAssets[sellToken].decimals);
        uint256 buyAmount = (sellValue * (10 ** supportedAssets[buyToken].decimals)) / buyPrice;

        // Update balances
        portfolios[portfolioId].assetBalances[sellToken] -= sellAmount;
        portfolios[portfolioId].assetBalances[buyToken] += buyAmount;

        // Create trade record
        _createTradeRecord(portfolioId, sellToken, buyToken, sellAmount, buyAmount, buyPrice);
    }

    function _getAssetRisk(string memory symbol) internal pure returns (uint256) {
        // Return risk score for different asset types (in basis points)
        if (keccak256(bytes(symbol)) == keccak256(bytes("AITBC"))) return 3000; // Medium risk
        if (keccak256(bytes(symbol)) == keccak256(bytes("USDC"))) return 500;   // Low risk
        if (keccak256(bytes(symbol)) == keccak256(bytes("ETH"))) return 6000;  // High risk
        return 4000; // Default medium risk
    }

    function _getStrategyRiskMultiplier(StrategyType strategyType) internal pure returns (uint256) {
        if (strategyType == StrategyType.CONSERVATIVE) return 5000;  // 0.5x
        if (strategyType == StrategyType.BALANCED) return 10000;   // 1.0x
        if (strategyType == StrategyType.AGGRESSIVE) return 15000; // 1.5x
        if (strategyType == StrategyType.DYNAMIC) return 12000;    // 1.2x
        return 10000; // Default 1.0x
    }

    // Admin functions

    function updateAssetPrice(string memory symbol, uint256 newPrice) external onlyOwner {
        require(supportedAssets[symbol].isActive, "Asset not supported");
        supportedAssets[symbol].priceOracle = newPrice;
    }

    function setRebalanceThreshold(uint256 newThreshold) external onlyOwner {
        require(newThreshold <= 10000, "Invalid threshold");
        rebalanceThreshold = newThreshold;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/AgentServiceMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";

/**
 * @title AgentServiceMarketplace
 * @dev Advanced marketplace for AI agents to discover, offer, and monetize their capabilities and services.
 */
contract AgentServiceMarketplace is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;

    IERC20 public aitbcToken;

    uint256 public serviceCounter;
    uint256 public subscriptionCounter;
    uint256 public platformFeePercentage = 250; // 2.5% in basis points (10000 = 100%)

    struct ServiceOffering {
        uint256 serviceId;
        address providerAgent;
        string capabilityURI;     // IPFS hash containing service metadata (inputs, outputs, SLA)
        uint256 pricePerUse;
        uint256 subscriptionPricePerMonth;
        bool isSubscriptionAvailable;
        bool isActive;
        uint256 totalUses;
        uint256 totalRevenue;
        uint256 reputationScore;  // Updated via cross-chain reputation or oracle
    }

    struct Subscription {
        uint256 subscriptionId;
        uint256 serviceId;
        address subscriberAgent;
        uint256 expiryTimestamp;
        bool isActive;
    }

    mapping(uint256 => ServiceOffering) public services;
    mapping(uint256 => Subscription) public subscriptions;
    mapping(address => uint256[]) public providerServices;
    mapping(address => uint256[]) public subscriberSubscriptions;

    // Events
    event ServiceRegistered(uint256 indexed serviceId, address indexed provider, string capabilityURI, uint256 pricePerUse);
    event ServiceUpdated(uint256 indexed serviceId, uint256 pricePerUse, bool isActive);
    event ServicePurchased(uint256 indexed serviceId, address indexed buyer, uint256 pricePaid);
    event SubscriptionCreated(uint256 indexed subscriptionId, uint256 indexed serviceId, address indexed subscriber, uint256 expiryTimestamp);
    event SubscriptionRenewed(uint256 indexed subscriptionId, uint256 newExpiryTimestamp);
    event PlatformFeeUpdated(uint256 newFeePercentage);
    event ServiceReputationUpdated(uint256 indexed serviceId, uint256 newScore);

    modifier serviceExists(uint256 _serviceId) {
        require(_serviceId < serviceCounter, "Service does not exist");
        _;
    }

    constructor(address _aitbcToken) {
        require(_aitbcToken != address(0), "Invalid token address");
        aitbcToken = IERC20(_aitbcToken);
    }

    /**
     * @dev Register a new agent capability/service
     * @param _capabilityURI IPFS hash for service metadata
     * @param _pricePerUse Price to pay per individual API/capability call
     * @param _subscriptionPricePerMonth Price for unlimited/tiered monthly access
     * @param _isSubscriptionAvailable Boolean flag enabling subscriptions
     */
    function registerService(
        string calldata _capabilityURI,
        uint256 _pricePerUse,
        uint256 _subscriptionPricePerMonth,
        bool _isSubscriptionAvailable
    ) external whenNotPaused returns (uint256) {
        require(bytes(_capabilityURI).length > 0, "Invalid URI");

        uint256 serviceId = serviceCounter++;

        services[serviceId] = ServiceOffering({
            serviceId: serviceId,
            providerAgent: msg.sender,
            capabilityURI: _capabilityURI,
            pricePerUse: _pricePerUse,
            subscriptionPricePerMonth: _subscriptionPricePerMonth,
            isSubscriptionAvailable: _isSubscriptionAvailable,
            isActive: true,
            totalUses: 0,
            totalRevenue: 0,
            reputationScore: 0
        });

        providerServices[msg.sender].push(serviceId);

        emit ServiceRegistered(serviceId, msg.sender, _capabilityURI, _pricePerUse);
        return serviceId;
    }

    /**
     * @dev Update an existing service offering
     */
    function updateService(
        uint256 _serviceId,
        uint256 _pricePerUse,
        uint256 _subscriptionPricePerMonth,
        bool _isSubscriptionAvailable,
        bool _isActive
    ) external serviceExists(_serviceId) {
        ServiceOffering storage service = services[_serviceId];
        require(service.providerAgent == msg.sender, "Not service provider");

        service.pricePerUse = _pricePerUse;
        service.subscriptionPricePerMonth = _subscriptionPricePerMonth;
        service.isSubscriptionAvailable = _isSubscriptionAvailable;
        service.isActive = _isActive;

        emit ServiceUpdated(_serviceId, _pricePerUse, _isActive);
    }

    /**
     * @dev Purchase a single use of an agent service
     */
    function purchaseService(uint256 _serviceId) external nonReentrant whenNotPaused serviceExists(_serviceId) {
        ServiceOffering storage service = services[_serviceId];
        require(service.isActive, "Service inactive");
        require(service.pricePerUse > 0, "Not available for single use");

        uint256 platformFee = (service.pricePerUse * platformFeePercentage) / 10000;
        uint256 providerAmount = service.pricePerUse - platformFee;

        // Transfer funds
        aitbcToken.safeTransferFrom(msg.sender, address(this), service.pricePerUse);

        // Pay provider
        if (providerAmount > 0) {
            aitbcToken.safeTransfer(service.providerAgent, providerAmount);
        }

        // Retain platform fee in contract (owner can withdraw)

        service.totalUses += 1;
        service.totalRevenue += providerAmount;

        emit ServicePurchased(_serviceId, msg.sender, service.pricePerUse);
    }

    /**
     * @dev Subscribe to an agent service for 30 days
     */
    function subscribeToService(uint256 _serviceId) external nonReentrant whenNotPaused serviceExists(_serviceId) returns (uint256) {
        ServiceOffering storage service = services[_serviceId];
        require(service.isActive, "Service inactive");
        require(service.isSubscriptionAvailable, "Subscriptions not enabled");

        uint256 platformFee = (service.subscriptionPricePerMonth * platformFeePercentage) / 10000;
        uint256 providerAmount = service.subscriptionPricePerMonth - platformFee;

        // Transfer funds
        aitbcToken.safeTransferFrom(msg.sender, address(this), service.subscriptionPricePerMonth);

        // Pay provider
        if (providerAmount > 0) {
            aitbcToken.safeTransfer(service.providerAgent, providerAmount);
        }

        service.totalRevenue += providerAmount;

        uint256 subId = subscriptionCounter++;
        uint256 expiry = block.timestamp + 30 days;

        subscriptions[subId] = Subscription({
            subscriptionId: subId,
            serviceId: _serviceId,
            subscriberAgent: msg.sender,
            expiryTimestamp: expiry,
            isActive: true
        });

        subscriberSubscriptions[msg.sender].push(subId);

        emit SubscriptionCreated(subId, _serviceId, msg.sender, expiry);
        return subId;
    }

    /**
     * @dev Check if a subscription is still active and valid
     */
    function checkSubscription(uint256 _subscriptionId) external view returns (bool) {
        Subscription memory sub = subscriptions[_subscriptionId];
        return sub.isActive && (block.timestamp < sub.expiryTimestamp);
    }

    /**
     * @dev Update the reputation score of a service (Oracle/Owner only)
     */
    function updateServiceReputation(uint256 _serviceId, uint256 _newScore) external onlyOwner serviceExists(_serviceId) {
        services[_serviceId].reputationScore = _newScore;
        emit ServiceReputationUpdated(_serviceId, _newScore);
    }

    /**
     * @dev Update platform fee percentage
     */
    function updatePlatformFee(uint256 _newFee) external onlyOwner {
        require(_newFee <= 1000, "Fee too high"); // Max 10%
        platformFeePercentage = _newFee;
        emit PlatformFeeUpdated(_newFee);
    }

    /**
     * @dev Withdraw accumulated platform fees
     */
    function withdrawPlatformFees() external onlyOwner {
        uint256 balance = aitbcToken.balanceOf(address(this));
        require(balance > 0, "No fees to withdraw");
        aitbcToken.safeTransfer(owner(), balance);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/AgentStaking.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "./PerformanceVerifier.sol";
import "./AIToken.sol";

/**
 * @title Agent Staking System
 * @dev Reputation-based yield farming for AI agents with dynamic APY calculation
 * @notice Allows users to stake AITBC tokens on agent wallets and earn rewards based on agent performance
 */
contract AgentStaking is Ownable, ReentrancyGuard, Pausable {

    // State variables
    IERC20 public aitbcToken;
    PerformanceVerifier public performanceVerifier;

    uint256 public stakeCounter;
    uint256 public baseAPY = 500; // 5% base APY in basis points
    uint256 public maxAPY = 2000; // 20% max APY in basis points
    uint256 public minStakeAmount = 100 * 10**18; // 100 AITBC minimum
    uint256 public maxStakeAmount = 100000 * 10**18; // 100k AITBC maximum
    uint256 public unbondingPeriod = 7 days;
    uint256 public rewardDistributionInterval = 1 days;
    uint256 public platformFeePercentage = 100; // 1% platform fee
    uint256 public earlyUnbondPenalty = 1000; // 10% penalty for early unbonding

    // Staking status
    enum StakeStatus { ACTIVE, UNBONDING, COMPLETED, SLASHED }

    // Agent performance tier
    enum PerformanceTier { BRONZE, SILVER, GOLD, PLATINUM, DIAMOND }

    // Structs
    struct Stake {
        uint256 stakeId;
        address staker;
        address agentWallet;
        uint256 amount;
        uint256 lockPeriod;
        uint256 startTime;
        uint256 endTime;
        StakeStatus status;
        uint256 accumulatedRewards;
        uint256 lastRewardTime;
        uint256 currentAPY;
        PerformanceTier agentTier;
        bool autoCompound;
    }

    struct AgentMetrics {
        address agentWallet;
        uint256 totalStaked;
        uint256 stakerCount;
        uint256 totalRewardsDistributed;
        uint256 averageAccuracy;
        uint256 totalSubmissions;
        uint256 successfulSubmissions;
        uint256 lastUpdateTime;
        PerformanceTier currentTier;
        uint256 tierScore;
    }

    struct StakingPool {
        address agentWallet;
        uint256 totalStaked;
        uint256 totalRewards;
        uint256 poolAPY;
        uint256 lastDistributionTime;
        mapping(address => uint256) stakerShares;
        address[] stakers;
    }

    struct RewardCalculation {
        uint256 baseRewards;
        uint256 performanceBonus;
        uint256 lockBonus;
        uint256 tierBonus;
        uint256 totalRewards;
        uint256 platformFee;
    }

    // Mappings
    mapping(uint256 => Stake) public stakes;
    mapping(address => uint256[]) public stakerStakes;
    mapping(address => uint256[]) public agentStakes;
    mapping(address => AgentMetrics) public agentMetrics;
    mapping(address => StakingPool) public stakingPools;
    mapping(PerformanceTier => uint256) public tierMultipliers;
    mapping(uint256 => uint256) public lockPeriodMultipliers;

    // Arrays
    address[] public supportedAgents;
    uint256[] public activeStakeIds;

    // Events
    event StakeCreated(
        uint256 indexed stakeId,
        address indexed staker,
        address indexed agentWallet,
        uint256 amount,
        uint256 lockPeriod,
        uint256 apy
    );

    event StakeUpdated(
        uint256 indexed stakeId,
        uint256 newAmount,
        uint256 newAPY
    );

    event RewardsDistributed(
        uint256 indexed stakeId,
        address indexed staker,
        uint256 rewardAmount,
        uint256 platformFee
    );

    event StakeUnbonded(
        uint256 indexed stakeId,
        address indexed staker,
        uint256 amount,
        uint256 penalty
    );

    event StakeCompleted(
        uint256 indexed stakeId,
        address indexed staker,
        uint256 totalAmount,
        uint256 totalRewards
    );

    event AgentTierUpdated(
        address indexed agentWallet,
        PerformanceTier oldTier,
        PerformanceTier newTier,
        uint256 tierScore
    );

    event PoolRewardsDistributed(
        address indexed agentWallet,
        uint256 totalRewards,
        uint256 stakerCount
    );

    event PlatformFeeCollected(
        uint256 indexed stakeId,
        uint256 feeAmount,
        address indexed collector
    );

    // Modifiers
    modifier stakeExists(uint256 _stakeId) {
        require(_stakeId < stakeCounter, "Stake does not exist");
        _;
    }

    modifier onlyStakeOwner(uint256 _stakeId) {
        require(stakes[_stakeId].staker == msg.sender, "Not stake owner");
        _;
    }

    modifier supportedAgent(address _agentWallet) {
        require(agentMetrics[_agentWallet].agentWallet != address(0) || _agentWallet == address(0), "Agent not supported");
        _;
    }

    modifier validStakeAmount(uint256 _amount) {
        require(_amount >= minStakeAmount && _amount <= maxStakeAmount, "Invalid stake amount");
        _;
    }

    modifier sufficientBalance(uint256 _amount) {
        require(aitbcToken.balanceOf(msg.sender) >= _amount, "Insufficient balance");
        _;
    }

    constructor(address _aitbcToken, address _performanceVerifier) {
        aitbcToken = IERC20(_aitbcToken);
        performanceVerifier = PerformanceVerifier(_performanceVerifier);

        // Set tier multipliers (in basis points)
        tierMultipliers[PerformanceTier.BRONZE] = 1000; // 1x
        tierMultipliers[PerformanceTier.SILVER] = 1200; // 1.2x
        tierMultipliers[PerformanceTier.GOLD] = 1500;   // 1.5x
        tierMultipliers[PerformanceTier.PLATINUM] = 2000; // 2x
        tierMultipliers[PerformanceTier.DIAMOND] = 3000; // 3x

        // Set lock period multipliers
        lockPeriodMultipliers[30 days] = 1100;   // 1.1x for 30 days
        lockPeriodMultipliers[90 days] = 1250;   // 1.25x for 90 days
        lockPeriodMultipliers[180 days] = 1500;  // 1.5x for 180 days
        lockPeriodMultipliers[365 days] = 2000;  // 2x for 365 days
    }

    /**
     * @dev Creates a new stake on an agent wallet
     * @param _agentWallet Address of the agent wallet
     * @param _amount Amount to stake
     * @param _lockPeriod Lock period in seconds
     * @param _autoCompound Whether to auto-compound rewards
     */
    function stakeOnAgent(
        address _agentWallet,
        uint256 _amount,
        uint256 _lockPeriod,
        bool _autoCompound
    ) external 
        supportedAgent(_agentWallet)
        validStakeAmount(_amount)
        sufficientBalance(_amount)
        nonReentrant 
        returns (uint256) 
    {
        require(_lockPeriod >= 1 days, "Lock period too short");
        require(_lockPeriod <= 365 days, "Lock period too long");

        uint256 stakeId = stakeCounter++;

        // Calculate initial APY
        PerformanceTier agentTier = _getAgentTier(_agentWallet);
        uint256 apy = _calculateAPY(_agentWallet, _lockPeriod, agentTier);

        Stake storage stake = stakes[stakeId];
        stake.stakeId = stakeId;
        stake.staker = msg.sender;
        stake.agentWallet = _agentWallet;
        stake.amount = _amount;
        stake.lockPeriod = _lockPeriod;
        stake.startTime = block.timestamp;
        stake.endTime = block.timestamp + _lockPeriod;
        stake.status = StakeStatus.ACTIVE;
        stake.accumulatedRewards = 0;
        stake.lastRewardTime = block.timestamp;
        stake.currentAPY = apy;
        stake.agentTier = agentTier;
        stake.autoCompound = _autoCompound;

        // Update agent metrics
        _updateAgentMetrics(_agentWallet, _amount, true);

        // Update staking pool
        _updateStakingPool(_agentWallet, msg.sender, _amount, true);

        // Update tracking arrays
        stakerStakes[msg.sender].push(stakeId);
        agentStakes[_agentWallet].push(stakeId);
        activeStakeIds.push(stakeId);

        // Transfer tokens to contract
        require(aitbcToken.transferFrom(msg.sender, address(this), _amount), "Transfer failed");

        emit StakeCreated(stakeId, msg.sender, _agentWallet, _amount, _lockPeriod, apy);

        return stakeId;
    }

    /**
     * @dev Adds more tokens to an existing stake
     * @param _stakeId Stake ID
     * @param _additionalAmount Additional amount to stake
     */
    function addToStake(
        uint256 _stakeId,
        uint256 _additionalAmount
    ) external 
        stakeExists(_stakeId)
        onlyStakeOwner(_stakeId)
        validStakeAmount(_additionalAmount)
        sufficientBalance(_additionalAmount)
        nonReentrant 
    {
        Stake storage stake = stakes[_stakeId];
        require(stake.status == StakeStatus.ACTIVE, "Stake not active");

        // Calculate new APY
        uint256 newTotalAmount = stake.amount + _additionalAmount;
        uint256 newAPY = _calculateAPY(stake.agentWallet, stake.lockPeriod, stake.agentTier);

        // Update stake
        stake.amount = newTotalAmount;
        stake.currentAPY = newAPY;

        // Update agent metrics
        _updateAgentMetrics(stake.agentWallet, _additionalAmount, true);

        // Update staking pool
        _updateStakingPool(stake.agentWallet, msg.sender, _additionalAmount, true);

        // Transfer additional tokens
        require(aitbcToken.transferFrom(msg.sender, address(this), _additionalAmount), "Transfer failed");

        emit StakeUpdated(_stakeId, newTotalAmount, newAPY);
    }

    /**
     * @dev Initiates unbonding for a stake
     * @param _stakeId Stake ID
     */
    function unbondStake(uint256 _stakeId) external 
        stakeExists(_stakeId)
        onlyStakeOwner(_stakeId)
        nonReentrant 
    {
        Stake storage stake = stakes[_stakeId];
        require(stake.status == StakeStatus.ACTIVE, "Stake not active");
        require(block.timestamp >= stake.endTime, "Lock period not ended");

        // Calculate final rewards
        _calculateRewards(_stakeId);

        stake.status = StakeStatus.UNBONDING;

        // Remove from active stakes
        _removeFromActiveStakes(_stakeId);
    }

    /**
     * @dev Completes unbonding and returns stake + rewards
     * @param _stakeId Stake ID
     */
    function completeUnbonding(uint256 _stakeId) external 
        stakeExists(_stakeId)
        onlyStakeOwner(_stakeId)
        nonReentrant 
    {
        Stake storage stake = stakes[_stakeId];
        require(stake.status == StakeStatus.UNBONDING, "Stake not unbonding");
        require(block.timestamp >= stake.endTime + unbondingPeriod, "Unbonding period not ended");

        uint256 totalAmount = stake.amount;
        uint256 totalRewards = stake.accumulatedRewards;

        // Apply early unbonding penalty if applicable
        uint256 penalty = 0;
        if (block.timestamp < stake.endTime + 30 days) {
            penalty = (totalAmount * earlyUnbondPenalty) / 10000;
            totalAmount -= penalty;
        }

        stake.status = StakeStatus.COMPLETED;

        // Update agent metrics
        _updateAgentMetrics(stake.agentWallet, stake.amount, false);

        // Update staking pool
        _updateStakingPool(stake.agentWallet, msg.sender, stake.amount, false);

        // Transfer tokens back to staker
        if (totalAmount > 0) {
            require(aitbcToken.transfer(msg.sender, totalAmount), "Stake transfer failed");
        }

        if (totalRewards > 0) {
            require(aitbcToken.transfer(msg.sender, totalRewards), "Rewards transfer failed");
        }

        emit StakeCompleted(_stakeId, msg.sender, totalAmount, totalRewards);
        emit StakeUnbonded(_stakeId, msg.sender, totalAmount, penalty);
    }

    /**
     * @dev Distributes agent earnings to stakers
     * @param _agentWallet Agent wallet address
     * @param _totalEarnings Total earnings to distribute
     */
    function distributeAgentEarnings(
        address _agentWallet,
        uint256 _totalEarnings
    ) external 
        supportedAgent(_agentWallet)
        nonReentrant 
    {
        require(_totalEarnings > 0, "No earnings to distribute");

        StakingPool storage pool = stakingPools[_agentWallet];
        require(pool.totalStaked > 0, "No stakers in pool");

        // Calculate platform fee
        uint256 platformFee = (_totalEarnings * platformFeePercentage) / 10000;
        uint256 distributableAmount = _totalEarnings - platformFee;

        // Transfer platform fee
        if (platformFee > 0) {
            require(aitbcToken.transferFrom(msg.sender, owner(), platformFee), "Platform fee transfer failed");
        }

        // Transfer distributable amount to contract
        require(aitbcToken.transferFrom(msg.sender, address(this), distributableAmount), "Earnings transfer failed");

        // Distribute to stakers proportionally
        uint256 totalDistributed = 0;
        for (uint256 i = 0; i < pool.stakers.length; i++) {
            address staker = pool.stakers[i];
            uint256 stakerShare = pool.stakerShares[staker];
            uint256 stakerReward = (distributableAmount * stakerShare) / pool.totalStaked;

            if (stakerReward > 0) {
                // Find and update all stakes for this staker on this agent
                uint256[] storage stakesForAgent = agentStakes[_agentWallet];
                for (uint256 j = 0; j < stakesForAgent.length; j++) {
                    uint256 stakeId = stakesForAgent[j];
                    Stake storage stake = stakes[stakeId];
                    if (stake.staker == staker && stake.status == StakeStatus.ACTIVE) {
                        stake.accumulatedRewards += stakerReward;
                        break;
                    }
                }
                totalDistributed += stakerReward;
            }
        }

        // Update agent metrics
        agentMetrics[_agentWallet].totalRewardsDistributed += totalDistributed;

        emit PoolRewardsDistributed(_agentWallet, totalDistributed, pool.stakers.length);
    }

    /**
     * @dev Updates agent performance metrics and tier
     * @param _agentWallet Agent wallet address
     * @param _accuracy Latest accuracy score
     * @param _successful Whether the submission was successful
     */
    function updateAgentPerformance(
        address _agentWallet,
        uint256 _accuracy,
        bool _successful
    ) external 
        supportedAgent(_agentWallet)
        nonReentrant 
    {
        AgentMetrics storage metrics = agentMetrics[_agentWallet];

        metrics.totalSubmissions++;
        if (_successful) {
            metrics.successfulSubmissions++;
        }

        // Update average accuracy (weighted average)
        uint256 totalAccuracy = metrics.averageAccuracy * (metrics.totalSubmissions - 1) + _accuracy;
        metrics.averageAccuracy = totalAccuracy / metrics.totalSubmissions;

        metrics.lastUpdateTime = block.timestamp;

        // Calculate new tier
        PerformanceTier newTier = _calculateAgentTier(_agentWallet);
        PerformanceTier oldTier = metrics.currentTier;

        if (newTier != oldTier) {
            metrics.currentTier = newTier;

            // Update APY for all active stakes on this agent
            uint256[] storage stakesForAgent = agentStakes[_agentWallet];
            for (uint256 i = 0; i < stakesForAgent.length; i++) {
                uint256 stakeId = stakesForAgent[i];
                Stake storage stake = stakes[stakeId];
                if (stake.status == StakeStatus.ACTIVE) {
                    stake.currentAPY = _calculateAPY(_agentWallet, stake.lockPeriod, newTier);
                    stake.agentTier = newTier;
                }
            }

            emit AgentTierUpdated(_agentWallet, oldTier, newTier, metrics.tierScore);
        }
    }

    /**
     * @dev Adds a supported agent
     * @param _agentWallet Agent wallet address
     * @param _initialTier Initial performance tier
     */
    function addSupportedAgent(
        address _agentWallet,
        PerformanceTier _initialTier
    ) external onlyOwner {
        require(_agentWallet != address(0), "Invalid agent address");
        require(agentMetrics[_agentWallet].agentWallet == address(0), "Agent already supported");

        agentMetrics[_agentWallet] = AgentMetrics({
            agentWallet: _agentWallet,
            totalStaked: 0,
            stakerCount: 0,
            totalRewardsDistributed: 0,
            averageAccuracy: 0,
            totalSubmissions: 0,
            successfulSubmissions: 0,
            lastUpdateTime: block.timestamp,
            currentTier: _initialTier,
            tierScore: _getTierScore(_initialTier)
        });

        // Initialize staking pool
        stakingPools[_agentWallet].agentWallet = _agentWallet;
        stakingPools[_agentWallet].totalStaked = 0;
        stakingPools[_agentWallet].totalRewards = 0;
        stakingPools[_agentWallet].poolAPY = baseAPY;
        stakingPools[_agentWallet].lastDistributionTime = block.timestamp;

        supportedAgents.push(_agentWallet);
    }

    /**
     * @dev Removes a supported agent
     * @param _agentWallet Agent wallet address
     */
    function removeSupportedAgent(address _agentWallet) external onlyOwner {
        require(agentMetrics[_agentWallet].agentWallet != address(0), "Agent not supported");
        require(agentMetrics[_agentWallet].totalStaked == 0, "Agent has active stakes");

        // Remove from supported agents
        for (uint256 i = 0; i < supportedAgents.length; i++) {
            if (supportedAgents[i] == _agentWallet) {
                supportedAgents[i] = supportedAgents[supportedAgents.length - 1];
                supportedAgents.pop();
                break;
            }
        }

        delete agentMetrics[_agentWallet];
        delete stakingPools[_agentWallet];
    }

    /**
     * @dev Updates configuration parameters
     * @param _baseAPY New base APY
     * @param _maxAPY New maximum APY
     * @param _platformFee New platform fee percentage
     */
    function updateConfiguration(
        uint256 _baseAPY,
        uint256 _maxAPY,
        uint256 _platformFee
    ) external onlyOwner {
        require(_baseAPY <= _maxAPY, "Base APY cannot exceed max APY");
        require(_maxAPY <= 5000, "Max APY too high"); // Max 50%
        require(_platformFee <= 500, "Platform fee too high"); // Max 5%

        baseAPY = _baseAPY;
        maxAPY = _maxAPY;
        platformFeePercentage = _platformFee;
    }

    // View functions

    /**
     * @dev Gets stake details
     * @param _stakeId Stake ID
     */
    function getStake(uint256 _stakeId) external view stakeExists(_stakeId) returns (
        address staker,
        address agentWallet,
        uint256 amount,
        uint256 lockPeriod,
        uint256 startTime,
        uint256 endTime,
        StakeStatus status,
        uint256 accumulatedRewards,
        uint256 currentAPY,
        PerformanceTier agentTier,
        bool autoCompound
    ) {
        Stake storage stake = stakes[_stakeId];
        return (
            stake.staker,
            stake.agentWallet,
            stake.amount,
            stake.lockPeriod,
            stake.startTime,
            stake.endTime,
            stake.status,
            stake.accumulatedRewards,
            stake.currentAPY,
            stake.agentTier,
            stake.autoCompound
        );
    }

    /**
     * @dev Gets agent metrics
     * @param _agentWallet Agent wallet address
     */
    function getAgentMetrics(address _agentWallet) external view returns (
        uint256 totalStaked,
        uint256 stakerCount,
        uint256 totalRewardsDistributed,
        uint256 averageAccuracy,
        uint256 totalSubmissions,
        uint256 successfulSubmissions,
        PerformanceTier currentTier,
        uint256 tierScore
    ) {
        AgentMetrics storage metrics = agentMetrics[_agentWallet];
        return (
            metrics.totalStaked,
            metrics.stakerCount,
            metrics.totalRewardsDistributed,
            metrics.averageAccuracy,
            metrics.totalSubmissions,
            metrics.successfulSubmissions,
            metrics.currentTier,
            metrics.tierScore
        );
    }

    /**
     * @dev Gets staking pool information
     * @param _agentWallet Agent wallet address
     */
    function getStakingPool(address _agentWallet) external view returns (
        uint256 totalStaked,
        uint256 totalRewards,
        uint256 poolAPY,
        uint256 stakerCount
    ) {
        StakingPool storage pool = stakingPools[_agentWallet];
        return (
            pool.totalStaked,
            pool.totalRewards,
            pool.poolAPY,
            pool.stakers.length
        );
    }

    /**
     * @dev Calculates current rewards for a stake
     * @param _stakeId Stake ID
     */
    function calculateRewards(uint256 _stakeId) external view stakeExists(_stakeId) returns (uint256) {
        Stake storage stake = stakes[_stakeId];
        if (stake.status != StakeStatus.ACTIVE) {
            return stake.accumulatedRewards;
        }

        uint256 timeElapsed = block.timestamp - stake.lastRewardTime;
        uint256 yearlyRewards = (stake.amount * stake.currentAPY) / 10000;
        uint256 currentRewards = (yearlyRewards * timeElapsed) / 365 days;

        return stake.accumulatedRewards + currentRewards;
    }

    /**
     * @dev Gets all stakes for a staker
     * @param _staker Staker address
     */
    function getStakerStakes(address _staker) external view returns (uint256[] memory) {
        return stakerStakes[_staker];
    }

    /**
     * @dev Gets all stakes for an agent
     * @param _agentWallet Agent wallet address
     */
    function getAgentStakes(address _agentWallet) external view returns (uint256[] memory) {
        return agentStakes[_agentWallet];
    }

    /**
     * @dev Gets all supported agents
     */
    function getSupportedAgents() external view returns (address[] memory) {
        return supportedAgents;
    }

    /**
     * @dev Gets all active stake IDs
     */
    function getActiveStakes() external view returns (uint256[] memory) {
        return activeStakeIds;
    }

    /**
     * @dev Calculates APY for a stake
     * @param _agentWallet Agent wallet address
     * @param _lockPeriod Lock period
     * @param _agentTier Agent performance tier
     */
    function calculateAPY(
        address _agentWallet,
        uint256 _lockPeriod,
        PerformanceTier _agentTier
    ) external view returns (uint256) {
        return _calculateAPY(_agentWallet, _lockPeriod, _agentTier);
    }

    // Internal functions

    function _calculateAPY(
        address _agentWallet,
        uint256 _lockPeriod,
        PerformanceTier _agentTier
    ) internal view returns (uint256) {
        uint256 tierMultiplier = tierMultipliers[_agentTier];
        uint256 lockMultiplier = lockPeriodMultipliers[_lockPeriod];

        uint256 apy = (baseAPY * tierMultiplier * lockMultiplier) / (10000 * 10000);

        // Cap at maximum APY
        return apy > maxAPY ? maxAPY : apy;
    }

    function _calculateRewards(uint256 _stakeId) internal {
        Stake storage stake = stakes[_stakeId];
        if (stake.status != StakeStatus.ACTIVE) {
            return;
        }

        uint256 timeElapsed = block.timestamp - stake.lastRewardTime;
        uint256 yearlyRewards = (stake.amount * stake.currentAPY) / 10000;
        uint256 currentRewards = (yearlyRewards * timeElapsed) / 365 days;

        stake.accumulatedRewards += currentRewards;
        stake.lastRewardTime = block.timestamp;

        // Auto-compound if enabled
        if (stake.autoCompound && currentRewards >= minStakeAmount) {
            stake.amount += currentRewards;
            stake.accumulatedRewards = 0;
        }
    }

    function _getAgentTier(address _agentWallet) internal view returns (PerformanceTier) {
        AgentMetrics storage metrics = agentMetrics[_agentWallet];
        return metrics.currentTier;
    }

    function _calculateAgentTier(address _agentWallet) internal view returns (PerformanceTier) {
        AgentMetrics storage metrics = agentMetrics[_agentWallet];

        uint256 successRate = metrics.totalSubmissions > 0 ? 
            (metrics.successfulSubmissions * 100) / metrics.totalSubmissions : 0;

        uint256 score = (metrics.averageAccuracy * 50) / 100 + (successRate * 50) / 100;

        if (score >= 95) return PerformanceTier.DIAMOND;
        if (score >= 90) return PerformanceTier.PLATINUM;
        if (score >= 80) return PerformanceTier.GOLD;
        if (score >= 70) return PerformanceTier.SILVER;
        return PerformanceTier.BRONZE;
    }

    function _getTierScore(PerformanceTier _tier) internal pure returns (uint256) {
        if (_tier == PerformanceTier.DIAMOND) return 95;
        if (_tier == PerformanceTier.PLATINUM) return 90;
        if (_tier == PerformanceTier.GOLD) return 80;
        if (_tier == PerformanceTier.SILVER) return 70;
        return 60;
    }

    function _updateAgentMetrics(address _agentWallet, uint256 _amount, bool _isStake) internal {
        AgentMetrics storage metrics = agentMetrics[_agentWallet];

        if (_isStake) {
            metrics.totalStaked += _amount;
            if (metrics.totalStaked == _amount) {
                metrics.stakerCount = 1;
            }
        } else {
            metrics.totalStaked -= _amount;
            if (metrics.totalStaked == 0) {
                metrics.stakerCount = 0;
            }
        }

        metrics.currentTier = _calculateAgentTier(_agentWallet);
        metrics.tierScore = _getTierScore(metrics.currentTier);
    }

    function _updateStakingPool(address _agentWallet, address _staker, uint256 _amount, bool _isStake) internal {
        StakingPool storage pool = stakingPools[_agentWallet];

        if (_isStake) {
            if (pool.stakerShares[_staker] == 0) {
                pool.stakers.push(_staker);
            }
            pool.stakerShares[_staker] += _amount;
            pool.totalStaked += _amount;
        } else {
            pool.stakerShares[_staker] -= _amount;
            pool.totalStaked -= _amount;

            // Remove staker from array if no shares left
            if (pool.stakerShares[_staker] == 0) {
                for (uint256 i = 0; i < pool.stakers.length; i++) {
                    if (pool.stakers[i] == _staker) {
                        pool.stakers[i] = pool.stakers[pool.stakers.length - 1];
                        pool.stakers.pop();
                        break;
                    }
                }
            }
        }

        // Update pool APY
        if (pool.totalStaked > 0) {
            pool.poolAPY = _calculateAPY(_agentWallet, 30 days, agentMetrics[_agentWallet].currentTier);
        }
    }

    function _removeFromActiveStakes(uint256 _stakeId) internal {
        for (uint256 i = 0; i < activeStakeIds.length; i++) {
            if (activeStakeIds[i] == _stakeId) {
                activeStakeIds[i] = activeStakeIds[activeStakeIds.length - 1];
                activeStakeIds.pop();
                break;
            }
        }
    }

    /**
     * @dev Emergency pause function
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpause function
     */
    function unpause() external onlyOwner {
        _unpause();
    }
}

contracts/AgentWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";

/**
 * @title AgentWallet
 * @dev Isolated agent-specific wallet for micro-transactions, funded by user allowances.
 */
contract AgentWallet is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public aitbcToken;

    // Structs
    struct Agent {
        address owner;
        uint256 balance;
        uint256 spendingLimit;
        uint256 totalSpent;
        bool isActive;
    }

    struct Transaction {
        uint256 txId;
        address agent;
        address recipient;
        uint256 amount;
        uint256 timestamp;
        string purpose;
    }

    // State Variables
    uint256 public txCounter;
    mapping(address => Agent) public agents;
    mapping(uint256 => Transaction) public transactions;
    mapping(address => uint256[]) public agentTransactions;

    // Events
    event AgentRegistered(address indexed agent, address indexed owner);
    event AgentDeactivated(address indexed agent);
    event FundsDeposited(address indexed agent, uint256 amount);
    event FundsWithdrawn(address indexed agent, uint256 amount);
    event SpendingLimitUpdated(address indexed agent, uint256 newLimit);
    event MicroTransactionExecuted(uint256 indexed txId, address indexed agent, address indexed recipient, uint256 amount, string purpose);

    // Modifiers
    modifier onlyAgentOwner(address _agent) {
        require(agents[_agent].owner == msg.sender, "Not agent owner");
        _;
    }

    modifier onlyActiveAgent(address _agent) {
        require(agents[_agent].isActive, "Agent is not active");
        _;
    }

    constructor(address _aitbcToken) {
        require(_aitbcToken != address(0), "Invalid token address");
        aitbcToken = IERC20(_aitbcToken);
    }

    /**
     * @dev Register a new agent wallet
     * @param _agent The address of the agent
     * @param _initialSpendingLimit The max the agent can spend
     */
    function registerAgent(address _agent, uint256 _initialSpendingLimit) external {
        require(_agent != address(0), "Invalid agent address");
        require(agents[_agent].owner == address(0), "Agent already registered");

        agents[_agent] = Agent({
            owner: msg.sender,
            balance: 0,
            spendingLimit: _initialSpendingLimit,
            totalSpent: 0,
            isActive: true
        });

        emit AgentRegistered(_agent, msg.sender);
    }

    /**
     * @dev Deactivate an agent
     * @param _agent The address of the agent
     */
    function deactivateAgent(address _agent) external onlyAgentOwner(_agent) {
        agents[_agent].isActive = false;
        emit AgentDeactivated(_agent);
    }

    /**
     * @dev Update the spending limit for an agent
     * @param _agent The address of the agent
     * @param _newLimit The new spending limit
     */
    function updateSpendingLimit(address _agent, uint256 _newLimit) external onlyAgentOwner(_agent) {
        agents[_agent].spendingLimit = _newLimit;
        emit SpendingLimitUpdated(_agent, _newLimit);
    }

    /**
     * @dev Deposit AITBC tokens into an agent's wallet
     * @param _agent The address of the agent
     * @param _amount The amount to deposit
     */
    function deposit(address _agent, uint256 _amount) external onlyActiveAgent(_agent) nonReentrant {
        require(_amount > 0, "Amount must be greater than 0");

        // Transfer tokens from the caller to this contract
        aitbcToken.safeTransferFrom(msg.sender, address(this), _amount);

        // Update agent balance
        agents[_agent].balance += _amount;

        emit FundsDeposited(_agent, _amount);
    }

    /**
     * @dev Withdraw AITBC tokens from an agent's wallet back to the owner
     * @param _agent The address of the agent
     * @param _amount The amount to withdraw
     */
    function withdraw(address _agent, uint256 _amount) external onlyAgentOwner(_agent) nonReentrant {
        require(_amount > 0, "Amount must be greater than 0");
        require(agents[_agent].balance >= _amount, "Insufficient balance");

        // Update agent balance
        agents[_agent].balance -= _amount;

        // Transfer tokens back to the owner
        aitbcToken.safeTransfer(msg.sender, _amount);

        emit FundsWithdrawn(_agent, _amount);
    }

    /**
     * @dev Execute a micro-transaction from the agent to a recipient
     * @param _recipient The address of the recipient
     * @param _amount The amount to send
     * @param _purpose The purpose of the transaction
     */
    function executeMicroTransaction(
        address _recipient, 
        uint256 _amount, 
        string calldata _purpose
    ) external onlyActiveAgent(msg.sender) nonReentrant returns (uint256) {
        require(_recipient != address(0), "Invalid recipient");
        require(_amount > 0, "Amount must be greater than 0");

        Agent storage agent = agents[msg.sender];

        require(agent.balance >= _amount, "Insufficient balance");
        require(agent.totalSpent + _amount <= agent.spendingLimit, "Spending limit exceeded");

        // Update agent balances
        agent.balance -= _amount;
        agent.totalSpent += _amount;

        // Create transaction record
        uint256 txId = txCounter++;
        transactions[txId] = Transaction({
            txId: txId,
            agent: msg.sender,
            recipient: _recipient,
            amount: _amount,
            timestamp: block.timestamp,
            purpose: _purpose
        });

        agentTransactions[msg.sender].push(txId);

        // Transfer tokens to the recipient
        aitbcToken.safeTransfer(_recipient, _amount);

        emit MicroTransactionExecuted(txId, msg.sender, _recipient, _amount, _purpose);

        return txId;
    }

    /**
     * @dev Get transaction history for an agent
     * @param _agent The address of the agent
     */
    function getAgentTransactions(address _agent) external view returns (uint256[] memory) {
        return agentTransactions[_agent];
    }
}

contracts/AIPowerRental.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "./ZKReceiptVerifier.sol";
import "./Groth16Verifier.sol";

/**
 * @title AI Power Rental Contract
 * @dev Smart contract for AI compute power rental agreements with performance verification
 * @notice Manages rental agreements between AI compute providers and consumers
 */
contract AIPowerRental is Ownable, ReentrancyGuard, Pausable {

    // State variables
    IERC20 public aitbcToken;
    ZKReceiptVerifier public zkVerifier;
    Groth16Verifier public groth16Verifier;

    uint256 public agreementCounter;
    uint256 public platformFeePercentage = 250; // 2.5% in basis points
    uint256 public minRentalDuration = 3600; // 1 hour minimum
    uint256 public maxRentalDuration = 86400 * 30; // 30 days maximum

    // Structs
    struct RentalAgreement {
        uint256 agreementId;
        address provider;
        address consumer;
        uint256 duration;
        uint256 price;
        uint256 startTime;
        uint256 endTime;
        uint256 platformFee;
        RentalStatus status;
        PerformanceMetrics performance;
        string gpuModel;
        uint256 computeUnits;
        bytes32 performanceProof;
    }

    struct PerformanceMetrics {
        uint256 responseTime;
        uint256 accuracy;
        uint256 availability;
        uint256 computePower;
        bool withinSLA;
        uint256 lastUpdateTime;
    }

    struct DisputeInfo {
        bool exists;
        address initiator;
        string reason;
        uint256 disputeTime;
        bool resolved;
        uint256 resolutionAmount;
    }

    // Enums
    enum RentalStatus {
        Created,
        Active,
        Completed,
        Disputed,
        Cancelled,
        Expired
    }

    // Mappings
    mapping(uint256 => RentalAgreement) public rentalAgreements;
    mapping(uint256 => DisputeInfo) public disputes;
    mapping(address => uint256[]) public providerAgreements;
    mapping(address => uint256[]) public consumerAgreements;
    mapping(address => bool) public authorizedProviders;
    mapping(address => bool) public authorizedConsumers;

    // Events
    event AgreementCreated(
        uint256 indexed agreementId,
        address indexed provider,
        address indexed consumer,
        uint256 duration,
        uint256 price,
        string gpuModel,
        uint256 computeUnits
    );

    event AgreementStarted(
        uint256 indexed agreementId,
        uint256 startTime,
        uint256 endTime
    );

    event AgreementCompleted(
        uint256 indexed agreementId,
        uint256 completionTime,
        bool withinSLA
    );

    event PaymentProcessed(
        uint256 indexed agreementId,
        address indexed provider,
        uint256 amount,
        uint256 platformFee
    );

    event PerformanceSubmitted(
        uint256 indexed agreementId,
        uint256 responseTime,
        uint256 accuracy,
        uint256 availability,
        bool withinSLA
    );

    event DisputeFiled(
        uint256 indexed agreementId,
        address indexed initiator,
        string reason
    );

    event DisputeResolved(
        uint256 indexed agreementId,
        uint256 resolutionAmount,
        bool resolvedInFavorOfProvider
    );

    event ProviderAuthorized(address indexed provider);
    event ProviderRevoked(address indexed provider);
    event ConsumerAuthorized(address indexed consumer);
    event ConsumerRevoked(address indexed consumer);

    // Modifiers
    modifier onlyAuthorizedProvider() {
        require(authorizedProviders[msg.sender], "Not authorized provider");
        _;
    }

    modifier onlyAuthorizedConsumer() {
        require(authorizedConsumers[msg.sender], "Not authorized consumer");
        _;
    }

    modifier onlyParticipant(uint256 _agreementId) {
        require(
            rentalAgreements[_agreementId].provider == msg.sender ||
            rentalAgreements[_agreementId].consumer == msg.sender,
            "Not agreement participant"
        );
        _;
    }

    modifier agreementExists(uint256 _agreementId) {
        require(_agreementId < agreementCounter, "Agreement does not exist");
        _;
    }

    modifier validStatus(uint256 _agreementId, RentalStatus _requiredStatus) {
        require(rentalAgreements[_agreementId].status == _requiredStatus, "Invalid agreement status");
        _;
    }

    // Constructor
    constructor(
        address _aitbcToken,
        address _zkVerifier,
        address _groth16Verifier
    ) {
        aitbcToken = IERC20(_aitbcToken);
        zkVerifier = ZKReceiptVerifier(_zkVerifier);
        groth16Verifier = Groth16Verifier(_groth16Verifier);
        agreementCounter = 0;
    }

    /**
     * @dev Creates a new rental agreement
     * @param _provider Address of the compute provider
     * @param _consumer Address of the compute consumer
     * @param _duration Duration in seconds
     * @param _price Total price in AITBC tokens
     * @param _gpuModel GPU model being rented
     * @param _computeUnits Amount of compute units
     */
    function createRental(
        address _provider,
        address _consumer,
        uint256 _duration,
        uint256 _price,
        string memory _gpuModel,
        uint256 _computeUnits
    ) external onlyAuthorizedConsumer nonReentrant whenNotPaused returns (uint256) {
        require(_duration >= minRentalDuration, "Duration too short");
        require(_duration <= maxRentalDuration, "Duration too long");
        require(_price > 0, "Price must be positive");
        require(authorizedProviders[_provider], "Provider not authorized");

        uint256 agreementId = agreementCounter++;
        uint256 platformFee = (_price * platformFeePercentage) / 10000;

        rentalAgreements[agreementId] = RentalAgreement({
            agreementId: agreementId,
            provider: _provider,
            consumer: _consumer,
            duration: _duration,
            price: _price,
            startTime: 0,
            endTime: 0,
            platformFee: platformFee,
            status: RentalStatus.Created,
            performance: PerformanceMetrics({
                responseTime: 0,
                accuracy: 0,
                availability: 0,
                computePower: 0,
                withinSLA: false,
                lastUpdateTime: 0
            }),
            gpuModel: _gpuModel,
            computeUnits: _computeUnits,
            performanceProof: bytes32(0)
        });

        providerAgreements[_provider].push(agreementId);
        consumerAgreements[_consumer].push(agreementId);

        emit AgreementCreated(
            agreementId,
            _provider,
            _consumer,
            _duration,
            _price,
            _gpuModel,
            _computeUnits
        );

        return agreementId;
    }

    /**
     * @dev Starts a rental agreement and locks payment
     * @param _agreementId ID of the agreement to start
     */
    function startRental(uint256 _agreementId) 
        external 
        agreementExists(_agreementId)
        validStatus(_agreementId, RentalStatus.Created)
        nonReentrant 
    {
        RentalAgreement storage agreement = rentalAgreements[_agreementId];

        require(msg.sender == agreement.consumer, "Only consumer can start");

        uint256 totalAmount = agreement.price + agreement.platformFee;

        // Transfer tokens from consumer to contract
        require(
            aitbcToken.transferFrom(msg.sender, address(this), totalAmount),
            "Payment transfer failed"
        );

        agreement.startTime = block.timestamp;
        agreement.endTime = block.timestamp + agreement.duration;
        agreement.status = RentalStatus.Active;

        emit AgreementStarted(_agreementId, agreement.startTime, agreement.endTime);
    }

    /**
     * @dev Completes a rental agreement and processes payment
     * @param _agreementId ID of the agreement to complete
     */
    function completeRental(uint256 _agreementId) 
        external 
        agreementExists(_agreementId)
        validStatus(_agreementId, RentalStatus.Active)
        onlyParticipant(_agreementId)
        nonReentrant 
    {
        RentalAgreement storage agreement = rentalAgreements[_agreementId];

        require(block.timestamp >= agreement.endTime, "Rental period not ended");

        agreement.status = RentalStatus.Completed;

        // Process payment to provider
        uint256 providerAmount = agreement.price;
        uint256 platformFeeAmount = agreement.platformFee;

        if (providerAmount > 0) {
            require(
                aitbcToken.transfer(agreement.provider, providerAmount),
                "Provider payment failed"
            );
        }

        if (platformFeeAmount > 0) {
            require(
                aitbcToken.transfer(owner(), platformFeeAmount),
                "Platform fee transfer failed"
            );
        }

        emit PaymentProcessed(_agreementId, agreement.provider, providerAmount, platformFeeAmount);
        emit AgreementCompleted(_agreementId, block.timestamp, agreement.performance.withinSLA);
    }

    /**
     * @dev Files a dispute for a rental agreement
     * @param _agreementId ID of the agreement
     * @param _reason Reason for the dispute
     */
    function disputeRental(uint256 _agreementId, string memory _reason) 
        external 
        agreementExists(_agreementId)
        onlyParticipant(_agreementId)
        nonReentrant 
    {
        RentalAgreement storage agreement = rentalAgreements[_agreementId];

        require(
            agreement.status == RentalStatus.Active || 
            agreement.status == RentalStatus.Completed,
            "Cannot dispute this agreement"
        );

        require(!disputes[_agreementId].exists, "Dispute already exists");

        disputes[_agreementId] = DisputeInfo({
            exists: true,
            initiator: msg.sender,
            reason: _reason,
            disputeTime: block.timestamp,
            resolved: false,
            resolutionAmount: 0
        });

        agreement.status = RentalStatus.Disputed;

        emit DisputeFiled(_agreementId, msg.sender, _reason);
    }

    /**
     * @dev Submits performance metrics for a rental agreement
     * @param _agreementId ID of the agreement
     * @param _responseTime Response time in milliseconds
     * @param _accuracy Accuracy percentage (0-100)
     * @param _availability Availability percentage (0-100)
     * @param _computePower Compute power utilized
     * @param _zkProof Zero-knowledge proof for performance verification
     */
    function submitPerformance(
        uint256 _agreementId,
        uint256 _responseTime,
        uint256 _accuracy,
        uint256 _availability,
        uint256 _computePower,
        bytes memory _zkProof
    ) external agreementExists(_agreementId) onlyAuthorizedProvider {
        RentalAgreement storage agreement = rentalAgreements[_agreementId];

        require(agreement.status == RentalStatus.Active, "Agreement not active");

        // Verify ZK proof
        bool proofValid = zkVerifier.verifyPerformanceProof(
            _agreementId,
            _responseTime,
            _accuracy,
            _availability,
            _computePower,
            _zkProof
        );

        require(proofValid, "Invalid performance proof");

        agreement.performance = PerformanceMetrics({
            responseTime: _responseTime,
            accuracy: _accuracy,
            availability: _availability,
            computePower: _computePower,
            withinSLA: _calculateSLA(_responseTime, _accuracy, _availability),
            lastUpdateTime: block.timestamp
        });

        agreement.performanceProof = keccak256(_zkProof);

        emit PerformanceSubmitted(
            _agreementId,
            _responseTime,
            _accuracy,
            _availability,
            agreement.performance.withinSLA
        );
    }

    /**
     * @dev Authorizes a provider to offer compute services
     * @param _provider Address of the provider
     */
    function authorizeProvider(address _provider) external onlyOwner {
        authorizedProviders[_provider] = true;
        emit ProviderAuthorized(_provider);
    }

    /**
     * @dev Revokes provider authorization
     * @param _provider Address of the provider
     */
    function revokeProvider(address _provider) external onlyOwner {
        authorizedProviders[_provider] = false;
        emit ProviderRevoked(_provider);
    }

    /**
     * @dev Authorizes a consumer to rent compute services
     * @param _consumer Address of the consumer
     */
    function authorizeConsumer(address _consumer) external onlyOwner {
        authorizedConsumers[_consumer] = true;
        emit ConsumerAuthorized(_consumer);
    }

    /**
     * @dev Revokes consumer authorization
     * @param _consumer Address of the consumer
     */
    function revokeConsumer(address _consumer) external onlyOwner {
        authorizedConsumers[_consumer] = false;
        emit ConsumerRevoked(_consumer);
    }

    /**
     * @dev Resolves a dispute
     * @param _agreementId ID of the disputed agreement
     * @param _resolutionAmount Amount to award to the winner
     * @param _resolveInFavorOfProvider True if resolving in favor of provider
     */
    function resolveDispute(
        uint256 _agreementId,
        uint256 _resolutionAmount,
        bool _resolveInFavorOfProvider
    ) external onlyOwner agreementExists(_agreementId) {
        require(disputes[_agreementId].exists, "No dispute exists");
        require(!disputes[_agreementId].resolved, "Dispute already resolved");

        RentalAgreement storage agreement = rentalAgreements[_agreementId];
        disputes[_agreementId].resolved = true;
        disputes[_agreementId].resolutionAmount = _resolutionAmount;

        address winner = _resolveInFavorOfProvider ? agreement.provider : agreement.consumer;

        if (_resolutionAmount > 0) {
            require(
                aitbcToken.transfer(winner, _resolutionAmount),
                "Resolution payment failed"
            );
        }

        emit DisputeResolved(_agreementId, _resolutionAmount, _resolveInFavorOfProvider);
    }

    /**
     * @dev Cancels a rental agreement (only before it starts)
     * @param _agreementId ID of the agreement to cancel
     */
    function cancelRental(uint256 _agreementId) 
        external 
        agreementExists(_agreementId)
        validStatus(_agreementId, RentalStatus.Created)
        onlyParticipant(_agreementId)
        nonReentrant 
    {
        RentalAgreement storage agreement = rentalAgreements[_agreementId];
        agreement.status = RentalStatus.Cancelled;
    }

    /**
     * @dev Emergency pause function
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpause function
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @dev Updates platform fee percentage
     * @param _newFee New fee percentage in basis points
     */
    function updatePlatformFee(uint256 _newFee) external onlyOwner {
        require(_newFee <= 1000, "Fee too high"); // Max 10%
        platformFeePercentage = _newFee;
    }

    // View functions

    /**
     * @dev Gets rental agreement details
     * @param _agreementId ID of the agreement
     */
    function getRentalAgreement(uint256 _agreementId) 
        external 
        view 
        agreementExists(_agreementId) 
        returns (RentalAgreement memory) 
    {
        return rentalAgreements[_agreementId];
    }

    /**
     * @dev Gets dispute information
     * @param _agreementId ID of the agreement
     */
    function getDisputeInfo(uint256 _agreementId) 
        external 
        view 
        agreementExists(_agreementId) 
        returns (DisputeInfo memory) 
    {
        return disputes[_agreementId];
    }

    /**
     * @dev Gets all agreements for a provider
     * @param _provider Address of the provider
     */
    function getProviderAgreements(address _provider) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return providerAgreements[_provider];
    }

    /**
     * @dev Gets all agreements for a consumer
     * @param _consumer Address of the consumer
     */
    function getConsumerAgreements(address _consumer) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return consumerAgreements[_consumer];
    }

    /**
     * @dev Calculates if performance meets SLA requirements
     */
    function _calculateSLA(
        uint256 _responseTime,
        uint256 _accuracy,
        uint256 _availability
    ) internal pure returns (bool) {
        return _responseTime <= 5000 && // <= 5 seconds
               _accuracy >= 95 && // >= 95% accuracy
               _availability >= 99; // >= 99% availability
    }
}

contracts/AIServiceAMM.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/utils/math/Math.sol";

/**
 * @title AIServiceAMM
 * @dev Automated Market Making protocol for AI service tokens
 * @notice Enables creation of liquidity pools and automated trading for AI services
 */
contract AIServiceAMM is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;
    using Math for uint256;

    // Constants
    uint256 public constant MINIMUM_LIQUIDITY = 1000; // Minimum liquidity to prevent rounding errors
    uint256 public constant BASIS_POINTS = 10000; // 100% in basis points
    uint256 public constant MAX_FEE = 1000; // Maximum 10% fee
    uint256 public constant FEE_PRECISION = 1000000; // Fee calculation precision

    // State variables
    uint256 public poolCounter;
    uint256 public defaultFee = 30; // 0.3% default fee
    uint256 public protocolFeePercentage = 20; // 20% of fees go to protocol
    address public protocolFeeRecipient;

    // Structs
    struct LiquidityPool {
        uint256 poolId;
        address tokenA;
        address tokenB;
        uint256 reserveA;
        uint256 reserveB;
        uint256 totalLiquidity;
        uint256 feePercentage; // Pool-specific fee in basis points
        address lpToken; // LP token address for this pool
        bool isActive;
        uint256 created_at;
        uint256 lastTradeTime;
        uint256 volume24h;
        uint256 fee24h;
    }

    struct LiquidityPosition {
        uint256 poolId;
        address provider;
        uint256 liquidityAmount;
        uint256 sharesOwned;
        uint256 lastDepositTime;
        uint256 unclaimedFees;
    }

    struct SwapParams {
        uint256 poolId;
        address tokenIn;
        address tokenOut;
        uint256 amountIn;
        uint256 minAmountOut;
        address recipient;
        uint256 deadline;
    }

    struct PoolMetrics {
        uint256 totalVolume;
        uint256 totalFees;
        uint256 tvl; // Total Value Locked
        uint256 apr; // Annual Percentage Rate for liquidity providers
        uint256 utilizationRate;
    }

    // Mappings
    mapping(uint256 => LiquidityPool) public pools;
    mapping(address => mapping(uint256 => LiquidityPosition)) public liquidityPositions;
    mapping(address => uint256[]) public providerPools;
    mapping(address => mapping(address => uint256)) public poolByTokenPair; // tokenA -> tokenB -> poolId

    // Arrays
    uint256[] public activePoolIds;

    // Events
    event PoolCreated(uint256 indexed poolId, address indexed tokenA, address indexed tokenB, uint256 fee);
    event LiquidityAdded(uint256 indexed poolId, address indexed provider, uint256 amountA, uint256 amountB, uint256 liquidity);
    event LiquidityRemoved(uint256 indexed poolId, address indexed provider, uint256 amountA, uint256 amountB, uint256 liquidity);
    event SwapExecuted(uint256 indexed poolId, address indexed recipient, address tokenIn, address tokenOut, uint256 amountIn, uint256 amountOut);
    event FeesCollected(uint256 indexed poolId, uint256 protocolFees, uint256 lpFees);
    event PoolUpdated(uint256 indexed poolId, uint256 reserveA, uint256 reserveB);

    // Modifiers
    modifier validPool(uint256 poolId) {
        require(poolId > 0 && poolId <= poolCounter, "Invalid pool ID");
        require(pools[poolId].isActive, "Pool not active");
        _;
    }

    modifier validDeadline(uint256 deadline) {
        require(block.timestamp <= deadline, "Transaction expired");
        _;
    }

    modifier nonZeroAmount(uint256 amount) {
        require(amount > 0, "Amount must be greater than 0");
        _;
    }

    constructor(address _protocolFeeRecipient) {
        protocolFeeRecipient = _protocolFeeRecipient;
    }

    /**
     * @dev Creates a new liquidity pool for two tokens
     * @param tokenA Address of the first token
     * @param tokenB Address of the second token
     * @param feePercentage Fee percentage in basis points
     * @return poolId The ID of the created pool
     */
    function createPool(
        address tokenA,
        address tokenB,
        uint256 feePercentage
    ) external nonReentrant whenNotPaused returns (uint256) {
        require(tokenA != tokenB, "Identical tokens");
        require(tokenA != address(0) && tokenB != address(0), "Zero address");
        require(feePercentage <= MAX_FEE, "Fee too high");
        require(poolByTokenPair[tokenA][tokenB] == 0 && poolByTokenPair[tokenB][tokenA] == 0, "Pool exists");

        // Ensure tokenA < tokenB for consistency
        if (tokenA > tokenB) {
            (tokenA, tokenB) = (tokenB, tokenA);
        }

        poolCounter++;
        uint256 poolId = poolCounter;

        pools[poolId] = LiquidityPool({
            poolId: poolId,
            tokenA: tokenA,
            tokenB: tokenB,
            reserveA: 0,
            reserveB: 0,
            totalLiquidity: 0,
            feePercentage: feePercentage,
            lpToken: address(this), // Simplified LP token representation
            isActive: true,
            created_at: block.timestamp,
            lastTradeTime: 0,
            volume24h: 0,
            fee24h: 0
        });

        poolByTokenPair[tokenA][tokenB] = poolId;
        poolByTokenPair[tokenB][tokenA] = poolId;
        activePoolIds.push(poolId);

        emit PoolCreated(poolId, tokenA, tokenB, feePercentage);
        return poolId;
    }

    /**
     * @dev Adds liquidity to a pool
     * @param poolId The pool ID
     * @param amountA Amount of tokenA to add
     * @param amountB Amount of tokenB to add
     * @param minAmountA Minimum amount of tokenA (slippage protection)
     * @param minAmountB Minimum amount of tokenB (slippage protection)
     * @return liquidityAmount The amount of liquidity tokens received
     */
    function addLiquidity(
        uint256 poolId,
        uint256 amountA,
        uint256 amountB,
        uint256 minAmountA,
        uint256 minAmountB
    ) 
        external 
        nonReentrant 
        whenNotPaused
        validPool(poolId)
        nonZeroAmount(amountA)
        nonZeroAmount(amountB)
        returns (uint256 liquidityAmount) 
    {
        LiquidityPool storage pool = pools[poolId];

        // Calculate optimal amounts based on current reserves
        uint256 optimalAmountB = _calculateOptimalAmountB(poolId, amountA);

        if (pool.reserveA == 0 && pool.reserveB == 0) {
            // First liquidity provider - set initial prices
            optimalAmountB = amountB;
        } else {
            require(amountB >= optimalAmountB, "Insufficient tokenB amount");
        }

        // Transfer tokens to contract
        IERC20(pool.tokenA).safeTransferFrom(msg.sender, address(this), amountA);
        IERC20(pool.tokenB).safeTransferFrom(msg.sender, address(this), amountB);

        // Calculate liquidity to mint
        if (pool.totalLiquidity == 0) {
            liquidityAmount = Math.sqrt(amountA * amountB) - MINIMUM_LIQUIDITY;
            pool.totalLiquidity += MINIMUM_LIQUIDITY; // Lock minimum liquidity
        } else {
            liquidityAmount = Math.min(
                (amountA * pool.totalLiquidity) / pool.reserveA,
                (amountB * pool.totalLiquidity) / pool.reserveB
            );
        }

        require(liquidityAmount > 0, "Insufficient liquidity minted");

        // Update pool reserves and liquidity
        pool.reserveA += amountA;
        pool.reserveB += amountB;
        pool.totalLiquidity += liquidityAmount;

        // Update or create liquidity position
        LiquidityPosition storage position = liquidityPositions[msg.sender][poolId];
        position.poolId = poolId;
        position.provider = msg.sender;
        position.liquidityAmount += liquidityAmount;
        position.sharesOwned = (position.liquidityAmount * BASIS_POINTS) / pool.totalLiquidity;
        position.lastDepositTime = block.timestamp;

        // Add to provider's pool list if new
        if (position.liquidityAmount == liquidityAmount) {
            providerPools[msg.sender].push(poolId);
        }

        emit LiquidityAdded(poolId, msg.sender, amountA, amountB, liquidityAmount);
        emit PoolUpdated(poolId, pool.reserveA, pool.reserveB);
    }

    /**
     * @dev Removes liquidity from a pool
     * @param poolId The pool ID
     * @param liquidityAmount Amount of liquidity to remove
     * @param minAmountA Minimum amount of tokenA to receive
     * @param minAmountB Minimum amount of tokenB to receive
     * @return amountA Amount of tokenA received
     * @return amountB Amount of tokenB received
     */
    function removeLiquidity(
        uint256 poolId,
        uint256 liquidityAmount,
        uint256 minAmountA,
        uint256 minAmountB
    ) 
        external 
        nonReentrant 
        whenNotPaused
        validPool(poolId)
        nonZeroAmount(liquidityAmount)
        returns (uint256 amountA, uint256 amountB) 
    {
        LiquidityPool storage pool = pools[poolId];
        LiquidityPosition storage position = liquidityPositions[msg.sender][poolId];

        require(position.liquidityAmount >= liquidityAmount, "Insufficient liquidity");

        // Calculate amounts to receive
        amountA = (liquidityAmount * pool.reserveA) / pool.totalLiquidity;
        amountB = (liquidityAmount * pool.reserveB) / pool.totalLiquidity;

        require(amountA >= minAmountA && amountB >= minAmountB, "Slippage protection");

        // Update pool reserves and liquidity
        pool.reserveA -= amountA;
        pool.reserveB -= amountB;
        pool.totalLiquidity -= liquidityAmount;

        // Update position
        position.liquidityAmount -= liquidityAmount;
        position.sharesOwned = (position.liquidityAmount * BASIS_POINTS) / pool.totalLiquidity;

        // Transfer tokens to user
        IERC20(pool.tokenA).safeTransfer(msg.sender, amountA);
        IERC20(pool.tokenB).safeTransfer(msg.sender, amountB);

        emit LiquidityRemoved(poolId, msg.sender, amountA, amountB, liquidityAmount);
        emit PoolUpdated(poolId, pool.reserveA, pool.reserveB);
    }

    /**
     * @dev Executes a token swap
     * @param params Swap parameters
     * @return amountOut Amount of tokens received
     */
    function swap(SwapParams calldata params) 
        external 
        nonReentrant 
        whenNotPaused
        validPool(params.poolId)
        validDeadline(params.deadline)
        nonZeroAmount(params.amountIn)
        returns (uint256 amountOut) 
    {
        LiquidityPool storage pool = pools[params.poolId];

        // Validate tokens
        require(
            params.tokenIn == pool.tokenA || params.tokenIn == pool.tokenB,
            "Invalid input token"
        );
        require(
            params.tokenOut == pool.tokenA || params.tokenOut == pool.tokenB,
            "Invalid output token"
        );
        require(params.tokenIn != params.tokenOut, "Same token swap");

        // Calculate output amount
        amountOut = _calculateSwapOutput(params.poolId, params.amountIn, params.tokenIn);
        require(amountOut >= params.minAmountOut, "Insufficient output amount");

        // Transfer input tokens
        IERC20(params.tokenIn).safeTransferFrom(msg.sender, address(this), params.amountIn);

        // Update reserves
        if (params.tokenIn == pool.tokenA) {
            pool.reserveA += params.amountIn;
            pool.reserveB -= amountOut;
        } else {
            pool.reserveB += params.amountIn;
            pool.reserveA -= amountOut;
        }

        // Transfer output tokens
        IERC20(params.tokenOut).safeTransfer(params.recipient, amountOut);

        // Update pool metrics
        pool.lastTradeTime = block.timestamp;
        pool.volume24h += params.amountIn;

        emit SwapExecuted(params.poolId, params.recipient, params.tokenIn, params.tokenOut, params.amountIn, amountOut);
        emit PoolUpdated(params.poolId, pool.reserveA, pool.reserveB);
    }

    /**
     * @dev Calculates the optimal amount of tokenB for adding liquidity
     * @param poolId The pool ID
     * @param amountIn Amount of tokenIn
     * @return amountOut Optimal amount of tokenOut
     */
    function calculateOptimalSwap(uint256 poolId, uint256 amountIn) 
        external 
        view 
        validPool(poolId)
        returns (uint256 amountOut) 
    {
        return _calculateSwapOutput(poolId, amountIn, pools[poolId].tokenA);
    }

    /**
     * @dev Gets pool metrics
     * @param poolId The pool ID
     * @return metrics Pool metrics
     */
    function getPoolMetrics(uint256 poolId) 
        external 
        view 
        validPool(poolId)
        returns (PoolMetrics memory metrics) 
    {
        LiquidityPool storage pool = pools[poolId];

        uint256 totalValue = pool.reserveA + pool.reserveB; // Simplified TVL calculation
        uint256 annualFees = pool.fee24h * 365; // Simplified APR calculation

        metrics = PoolMetrics({
            totalVolume: pool.volume24h,
            totalFees: pool.fee24h,
            tvl: totalValue,
            apr: totalValue > 0 ? (annualFees * BASIS_POINTS) / totalValue : 0,
            utilizationRate: pool.totalLiquidity > 0 ? ((pool.volume24h * BASIS_POINTS) / pool.totalLiquidity) : 0
        });
    }

    /**
     * @dev Gets the amount of liquidity tokens a user owns in a pool
     * @param provider The liquidity provider address
     * @param poolId The pool ID
     * @return liquidityAmount Amount of liquidity tokens
     */
    function getLiquidityAmount(address provider, uint256 poolId) 
        external 
        view 
        returns (uint256 liquidityAmount) 
    {
        return liquidityPositions[provider][poolId].liquidityAmount;
    }

    // Internal functions

    function _calculateOptimalAmountB(uint256 poolId, uint256 amountA) internal view returns (uint256) {
        LiquidityPool storage pool = pools[poolId];
        if (pool.reserveA == 0) return 0;
        return (amountA * pool.reserveB) / pool.reserveA;
    }

    function _calculateSwapOutput(uint256 poolId, uint256 amountIn, address tokenIn) 
        internal 
        view 
        returns (uint256 amountOut) 
    {
        LiquidityPool storage pool = pools[poolId];

        uint256 reserveIn;
        uint256 reserveOut;

        if (tokenIn == pool.tokenA) {
            reserveIn = pool.reserveA;
            reserveOut = pool.reserveB;
        } else {
            reserveIn = pool.reserveB;
            reserveOut = pool.reserveA;
        }

        // Apply fee
        uint256 feeAmount = (amountIn * pool.feePercentage) / BASIS_POINTS;
        uint256 amountInAfterFee = amountIn - feeAmount;

        // Calculate output using constant product formula
        amountOut = (amountInAfterFee * reserveOut) / (reserveIn + amountInAfterFee);

        // Ensure minimum output
        require(amountOut > 0, "Insufficient output amount");
        require(reserveOut > amountOut, "Insufficient liquidity");
    }

    function _collectFees(uint256 poolId) internal {
        LiquidityPool storage pool = pools[poolId];

        if (pool.fee24h == 0) return;

        uint256 protocolFees = (pool.fee24h * protocolFeePercentage) / BASIS_POINTS;
        uint256 lpFees = pool.fee24h - protocolFees;

        // Distribute fees to liquidity providers
        if (lpFees > 0 && pool.totalLiquidity > 0) {
            for (uint i = 0; i < activePoolIds.length; i++) {
                uint256 currentPoolId = activePoolIds[i];
                if (currentPoolId == poolId) {
                    // Simplified fee distribution
                    // In production, this would be more sophisticated
                    break;
                }
            }
        }

        emit FeesCollected(poolId, protocolFees, lpFees);
        pool.fee24h = 0;
    }

    // Admin functions

    function setProtocolFeeRecipient(address newRecipient) external onlyOwner {
        require(newRecipient != address(0), "Invalid address");
        protocolFeeRecipient = newRecipient;
    }

    function setProtocolFeePercentage(uint256 newPercentage) external onlyOwner {
        require(newPercentage <= BASIS_POINTS, "Invalid percentage");
        protocolFeePercentage = newPercentage;
    }

    function setDefaultFee(uint256 newFee) external onlyOwner {
        require(newFee <= MAX_FEE, "Fee too high");
        defaultFee = newFee;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // Emergency functions

    function emergencyWithdraw(address token, uint256 amount) external onlyOwner {
        IERC20(token).safeTransfer(owner(), amount);
    }

    function emergencyPause() external onlyOwner {
        _pause();
    }
}

contracts/AITBCPaymentProcessor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "./AIPowerRental.sol";

/**
 * @title AITBC Payment Processor
 * @dev Advanced payment processing contract with escrow, automated releases, and dispute resolution
 * @notice Handles AITBC token payments for AI power rental services
 */
contract AITBCPaymentProcessor is Ownable, ReentrancyGuard, Pausable {

    // State variables
    IERC20 public aitbcToken;
    AIPowerRental public aiPowerRental;

    uint256 public paymentCounter;
    uint256 public platformFeePercentage = 250; // 2.5% in basis points
    uint256 public disputeResolutionFee = 100; // 1% in basis points
    uint256 public minPaymentAmount = 1e15; // 0.001 AITBC minimum
    uint256 public maxPaymentAmount = 1e22; // 10,000 AITBC maximum

    // Structs
    struct Payment {
        uint256 paymentId;
        address from;
        address to;
        uint256 amount;
        uint256 platformFee;
        uint256 disputeFee;
        PaymentStatus status;
        uint256 releaseTime;
        uint256 createdTime;
        uint256 confirmedTime;
        bytes32 agreementId;
        string paymentPurpose;
        ReleaseCondition releaseCondition;
        bytes32 conditionHash;
    }

    struct EscrowAccount {
        uint256 escrowId;
        address depositor;
        address beneficiary;
        uint256 amount;
        uint256 releaseTime;
        bool isReleased;
        bool isRefunded;
        bytes32 releaseCondition;
        uint256 createdTime;
        EscrowType escrowType;
    }

    struct ScheduledPayment {
        uint256 scheduleId;
        uint256 paymentId;
        uint256 nextReleaseTime;
        uint256 releaseInterval;
        uint256 totalReleases;
        uint256 releasedCount;
        bool isActive;
    }

    // Enums
    enum PaymentStatus {
        Created,
        Confirmed,
        HeldInEscrow,
        Released,
        Refunded,
        Disputed,
        Cancelled
    }

    enum EscrowType {
        Standard,
        PerformanceBased,
        TimeBased,
        Conditional
    }

    enum ReleaseCondition {
        Immediate,
        Manual,
        Performance,
        TimeBased,
        DisputeResolution
    }

    // Mappings
    mapping(uint256 => Payment) public payments;
    mapping(uint256 => EscrowAccount) public escrowAccounts;
    mapping(uint256 => ScheduledPayment) public scheduledPayments;
    mapping(address => uint256[]) public senderPayments;
    mapping(address => uint256[]) public recipientPayments;
    mapping(bytes32 => uint256) public agreementPayments;
    mapping(address => uint256) public userEscrowBalance;
    mapping(address => bool) public authorizedPayees;
    mapping(address => bool) public authorizedPayers;

    // Events
    event PaymentCreated(
        uint256 indexed paymentId,
        address indexed from,
        address indexed to,
        uint256 amount,
        bytes32 agreementId,
        string paymentPurpose
    );

    event PaymentConfirmed(
        uint256 indexed paymentId,
        uint256 confirmedTime,
        bytes32 transactionHash
    );

    event PaymentReleased(
        uint256 indexed paymentId,
        address indexed to,
        uint256 amount,
        uint256 platformFee
    );

    event PaymentRefunded(
        uint256 indexed paymentId,
        address indexed to,
        uint256 amount,
        string reason
    );

    event EscrowCreated(
        uint256 indexed escrowId,
        address indexed depositor,
        address indexed beneficiary,
        uint256 amount,
        EscrowType escrowType
    );

    event EscrowReleased(
        uint256 indexed escrowId,
        uint256 amount,
        bytes32 conditionHash
    );

    event EscrowRefunded(
        uint256 indexed escrowId,
        address indexed depositor,
        uint256 amount,
        string reason
    );

    event ScheduledPaymentCreated(
        uint256 indexed scheduleId,
        uint256 indexed paymentId,
        uint256 nextReleaseTime,
        uint256 releaseInterval
    );

    event ScheduledPaymentReleased(
        uint256 indexed scheduleId,
        uint256 indexed paymentId,
        uint256 releaseCount
    );

    event DisputeInitiated(
        uint256 indexed paymentId,
        address indexed initiator,
        string reason
    );

    event DisputeResolved(
        uint256 indexed paymentId,
        uint256 resolutionAmount,
        bool resolvedInFavorOfPayer
    );

    event PlatformFeeCollected(
        uint256 indexed paymentId,
        uint256 feeAmount,
        address indexed collector
    );

    // Modifiers
    modifier onlyAuthorizedPayer() {
        require(authorizedPayers[msg.sender], "Not authorized payer");
        _;
    }

    modifier onlyAuthorizedPayee() {
        require(authorizedPayees[msg.sender], "Not authorized payee");
        _;
    }

    modifier paymentExists(uint256 _paymentId) {
        require(_paymentId < paymentCounter, "Payment does not exist");
        _;
    }

    modifier validStatus(uint256 _paymentId, PaymentStatus _requiredStatus) {
        require(payments[_paymentId].status == _requiredStatus, "Invalid payment status");
        _;
    }

    modifier sufficientBalance(address _user, uint256 _amount) {
        require(aitbcToken.balanceOf(_user) >= _amount, "Insufficient balance");
        _;
    }

    modifier sufficientAllowance(address _user, uint256 _amount) {
        require(aitbcToken.allowance(_user, address(this)) >= _amount, "Insufficient allowance");
        _;
    }

    // Constructor
    constructor(address _aitbcToken, address _aiPowerRental) {
        aitbcToken = IERC20(_aitbcToken);
        aiPowerRental = AIPowerRental(_aiPowerRental);
        paymentCounter = 0;
    }

    /**
     * @dev Creates a new payment
     * @param _to Recipient address
     * @param _amount Payment amount
     * @param _agreementId Associated agreement ID
     * @param _paymentPurpose Purpose of the payment
     * @param _releaseCondition Release condition
     */
    function createPayment(
        address _to,
        uint256 _amount,
        bytes32 _agreementId,
        string memory _paymentPurpose,
        ReleaseCondition _releaseCondition
    ) external onlyAuthorizedPayer sufficientBalance(msg.sender, _amount) sufficientAllowance(msg.sender, _amount) nonReentrant whenNotPaused returns (uint256) {
        require(_amount >= minPaymentAmount, "Amount below minimum");
        require(_amount <= maxPaymentAmount, "Amount above maximum");
        require(_to != address(0), "Invalid recipient");
        require(authorizedPayees[_to], "Recipient not authorized");

        uint256 paymentId = paymentCounter++;

        // Calculate fees and create payment
        _createPaymentWithFees(paymentId, _to, _amount, _agreementId, _paymentPurpose, _releaseCondition);

        // Update tracking arrays
        _updatePaymentTracking(paymentId, _to, _agreementId);

        // Transfer tokens
        _transferTokensForPayment(_amount);

        emit PaymentCreated(paymentId, msg.sender, _to, _amount, _agreementId, _paymentPurpose);

        return paymentId;
    }

    function _createPaymentWithFees(
        uint256 _paymentId,
        address _to,
        uint256 _amount,
        bytes32 _agreementId,
        string memory _paymentPurpose,
        ReleaseCondition _releaseCondition
    ) internal {
        uint256 platformFee = (_amount * platformFeePercentage) / 10000;
        uint256 disputeFee = (_amount * disputeResolutionFee) / 10000;

        payments[_paymentId] = Payment({
            paymentId: _paymentId,
            from: msg.sender,
            to: _to,
            amount: _amount,
            platformFee: platformFee,
            disputeFee: disputeFee,
            status: PaymentStatus.Created,
            releaseTime: 0,
            createdTime: block.timestamp,
            confirmedTime: 0,
            agreementId: _agreementId,
            paymentPurpose: _paymentPurpose,
            releaseCondition: _releaseCondition,
            conditionHash: bytes32(0)
        });
    }

    function _updatePaymentTracking(uint256 _paymentId, address _to, bytes32 _agreementId) internal {
        senderPayments[msg.sender].push(_paymentId);
        recipientPayments[_to].push(_paymentId);

        if (_agreementId != bytes32(0)) {
            agreementPayments[_agreementId] = _paymentId;
        }
    }

    function _transferTokensForPayment(uint256 _amount) internal {
        uint256 platformFee = (_amount * platformFeePercentage) / 10000;
        uint256 disputeFee = (_amount * disputeResolutionFee) / 10000;
        uint256 totalAmount = _amount + platformFee + disputeFee;

        require(
            aitbcToken.transferFrom(msg.sender, address(this), totalAmount),
            "Payment transfer failed"
        );
    }

    /**
     * @dev Confirms a payment with transaction hash
     * @param _paymentId ID of the payment
     * @param _transactionHash Blockchain transaction hash
     */
    function confirmPayment(uint256 _paymentId, bytes32 _transactionHash) 
        external 
        paymentExists(_paymentId)
        validStatus(_paymentId, PaymentStatus.Created)
        nonReentrant 
    {
        Payment storage payment = payments[_paymentId];

        require(msg.sender == payment.from, "Only payer can confirm");

        payment.status = PaymentStatus.Confirmed;
        payment.confirmedTime = block.timestamp;
        payment.conditionHash = _transactionHash;

        // Handle immediate release
        if (payment.releaseCondition == ReleaseCondition.Immediate) {
            _releasePayment(_paymentId);
        } else if (payment.releaseCondition == ReleaseCondition.TimeBased) {
            payment.status = PaymentStatus.HeldInEscrow;
            payment.releaseTime = block.timestamp + 1 hours; // Default 1 hour hold
        } else {
            payment.status = PaymentStatus.HeldInEscrow;
        }

        emit PaymentConfirmed(_paymentId, block.timestamp, _transactionHash);
    }

    /**
     * @dev Releases a payment to the recipient
     * @param _paymentId ID of the payment
     */
    function releasePayment(uint256 _paymentId) 
        external 
        paymentExists(_paymentId)
        nonReentrant 
    {
        Payment storage payment = payments[_paymentId];

        require(
            payment.status == PaymentStatus.Confirmed || 
            payment.status == PaymentStatus.HeldInEscrow,
            "Payment not ready for release"
        );

        if (payment.releaseCondition == ReleaseCondition.Manual) {
            require(msg.sender == payment.from, "Only payer can release manually");
        } else if (payment.releaseCondition == ReleaseCondition.TimeBased) {
            require(block.timestamp >= payment.releaseTime, "Release time not reached");
        }

        _releasePayment(_paymentId);
    }

    /**
     * @dev Creates an escrow account
     * @param _beneficiary Beneficiary address
     * @param _amount Amount to lock in escrow
     * @param _releaseTime Release time (0 for no time limit)
     * @param _escrowType Type of escrow
     * @param _releaseCondition Release condition hash
     */
    function createEscrow(
        address _beneficiary,
        uint256 _amount,
        uint256 _releaseTime,
        EscrowType _escrowType,
        bytes32 _releaseCondition
    ) external onlyAuthorizedPayer sufficientBalance(msg.sender, _amount) sufficientAllowance(msg.sender, _amount) nonReentrant whenNotPaused returns (uint256) {
        require(_beneficiary != address(0), "Invalid beneficiary");
        require(_amount >= minPaymentAmount, "Amount below minimum");

        uint256 escrowId = paymentCounter++;

        escrowAccounts[escrowId] = EscrowAccount({
            escrowId: escrowId,
            depositor: msg.sender,
            beneficiary: _beneficiary,
            amount: _amount,
            releaseTime: _releaseTime,
            isReleased: false,
            isRefunded: false,
            releaseCondition: _releaseCondition,
            createdTime: block.timestamp,
            escrowType: _escrowType
        });

        // Transfer tokens to contract
        require(
            aitbcToken.transferFrom(msg.sender, address(this), _amount),
            "Escrow transfer failed"
        );

        userEscrowBalance[msg.sender] += _amount;

        emit EscrowCreated(escrowId, msg.sender, _beneficiary, _amount, _escrowType);

        return escrowId;
    }

    /**
     * @dev Releases escrow to beneficiary
     * @param _escrowId ID of the escrow account
     */
    function releaseEscrow(uint256 _escrowId) 
        external 
        nonReentrant 
    {
        EscrowAccount storage escrow = escrowAccounts[_escrowId];

        require(!escrow.isReleased, "Escrow already released");
        require(!escrow.isRefunded, "Escrow already refunded");
        require(
            escrow.releaseTime == 0 || block.timestamp >= escrow.releaseTime,
            "Release time not reached"
        );

        escrow.isReleased = true;
        userEscrowBalance[escrow.depositor] -= escrow.amount;

        require(
            aitbcToken.transfer(escrow.beneficiary, escrow.amount),
            "Escrow release failed"
        );

        emit EscrowReleased(_escrowId, escrow.amount, escrow.releaseCondition);
    }

    /**
     * @dev Refunds escrow to depositor
     * @param _escrowId ID of the escrow account
     * @param _reason Reason for refund
     */
    function refundEscrow(uint256 _escrowId, string memory _reason) 
        external 
        nonReentrant 
    {
        EscrowAccount storage escrow = escrowAccounts[_escrowId];

        require(!escrow.isReleased, "Escrow already released");
        require(!escrow.isRefunded, "Escrow already refunded");
        require(
            msg.sender == escrow.depositor || msg.sender == owner(),
            "Only depositor or owner can refund"
        );

        escrow.isRefunded = true;
        userEscrowBalance[escrow.depositor] -= escrow.amount;

        require(
            aitbcToken.transfer(escrow.depositor, escrow.amount),
            "Escrow refund failed"
        );

        emit EscrowRefunded(_escrowId, escrow.depositor, escrow.amount, _reason);
    }

    /**
     * @dev Initiates a dispute for a payment
     * @param _paymentId ID of the payment
     * @param _reason Reason for dispute
     */
    function initiateDispute(uint256 _paymentId, string memory _reason) 
        external 
        paymentExists(_paymentId)
        nonReentrant 
    {
        Payment storage payment = payments[_paymentId];

        require(
            payment.status == PaymentStatus.Confirmed || 
            payment.status == PaymentStatus.HeldInEscrow,
            "Cannot dispute this payment"
        );

        require(
            msg.sender == payment.from || msg.sender == payment.to,
            "Only payment participants can dispute"
        );

        payment.status = PaymentStatus.Disputed;

        emit DisputeInitiated(_paymentId, msg.sender, _reason);
    }

    /**
     * @dev Resolves a dispute
     * @param _paymentId ID of the disputed payment
     * @param _resolutionAmount Amount to award to the winner
     * @param _resolveInFavorOfPayer True if resolving in favor of payer
     */
    function resolveDispute(
        uint256 _paymentId,
        uint256 _resolutionAmount,
        bool _resolveInFavorOfPayer
    ) external onlyOwner paymentExists(_paymentId) nonReentrant {
        Payment storage payment = payments[_paymentId];

        require(payment.status == PaymentStatus.Disputed, "Payment not disputed");
        require(_resolutionAmount <= payment.amount, "Resolution amount too high");

        address winner = _resolveInFavorOfPayer ? payment.from : payment.to;
        address loser = _resolveInFavorOfPayer ? payment.to : payment.from;

        // Calculate refund for loser
        uint256 refundAmount = payment.amount - _resolutionAmount;

        // Transfer resolution amount to winner
        if (_resolutionAmount > 0) {
            require(
                aitbcToken.transfer(winner, _resolutionAmount),
                "Resolution payment failed"
            );
        }

        // Refund remaining amount to loser
        if (refundAmount > 0) {
            require(
                aitbcToken.transfer(loser, refundAmount),
                "Refund payment failed"
            );
        }

        payment.status = PaymentStatus.Released;

        emit DisputeResolved(_paymentId, _resolutionAmount, _resolveInFavorOfPayer);
    }

    /**
     * @dev Claims platform fees
     * @param _paymentId ID of the payment
     */
    function claimPlatformFee(uint256 _paymentId) 
        external 
        onlyOwner 
        paymentExists(_paymentId)
        nonReentrant 
    {
        Payment storage payment = payments[_paymentId];

        require(payment.status == PaymentStatus.Released, "Payment not released");
        require(payment.platformFee > 0, "No platform fee to claim");

        uint256 feeAmount = payment.platformFee;
        payment.platformFee = 0;

        require(
            aitbcToken.transfer(owner(), feeAmount),
            "Platform fee transfer failed"
        );

        emit PlatformFeeCollected(_paymentId, feeAmount, owner());
    }

    /**
     * @dev Authorizes a payee
     * @param _payee Address to authorize
     */
    function authorizePayee(address _payee) external onlyOwner {
        authorizedPayees[_payee] = true;
    }

    /**
     * @dev Revokes payee authorization
     * @param _payee Address to revoke
     */
    function revokePayee(address _payee) external onlyOwner {
        authorizedPayees[_payee] = false;
    }

    /**
     * @dev Authorizes a payer
     * @param _payer Address to authorize
     */
    function authorizePayer(address _payer) external onlyOwner {
        authorizedPayers[_payer] = true;
    }

    /**
     * @dev Revokes payer authorization
     * @param _payer Address to revoke
     */
    function revokePayer(address _payer) external onlyOwner {
        authorizedPayers[_payer] = false;
    }

    /**
     * @dev Updates platform fee percentage
     * @param _newFee New fee percentage in basis points
     */
    function updatePlatformFee(uint256 _newFee) external onlyOwner {
        require(_newFee <= 1000, "Fee too high"); // Max 10%
        platformFeePercentage = _newFee;
    }

    /**
     * @dev Emergency pause function
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @dev Unpause function
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    // Internal functions

    function _releasePayment(uint256 _paymentId) internal {
        Payment storage payment = payments[_paymentId];

        payment.status = PaymentStatus.Released;

        // Transfer amount to recipient
        require(
            aitbcToken.transfer(payment.to, payment.amount),
            "Payment transfer failed"
        );

        // Transfer platform fee to owner
        if (payment.platformFee > 0) {
            require(
                aitbcToken.transfer(owner(), payment.platformFee),
                "Platform fee transfer failed"
            );
        }

        emit PaymentReleased(_paymentId, payment.to, payment.amount, payment.platformFee);
    }

    // View functions

    /**
     * @dev Gets payment details
     * @param _paymentId ID of the payment
     */
    function getPayment(uint256 _paymentId) 
        external 
        view 
        paymentExists(_paymentId) 
        returns (Payment memory) 
    {
        return payments[_paymentId];
    }

    /**
     * @dev Gets escrow account details
     * @param _escrowId ID of the escrow account
     */
    function getEscrowAccount(uint256 _escrowId) 
        external 
        view 
        returns (EscrowAccount memory) 
    {
        return escrowAccounts[_escrowId];
    }

    /**
     * @dev Gets all payments for a sender
     * @param _sender Address of the sender
     */
    function getSenderPayments(address _sender) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return senderPayments[_sender];
    }

    /**
     * @dev Gets all payments for a recipient
     * @param _recipient Address of the recipient
     */
    function getRecipientPayments(address _recipient) 
        external 
        view 
        returns (uint256[] memory) 
    {
        return recipientPayments[_recipient];
    }

    /**
     * @dev Gets payment associated with an agreement
     * @param _agreementId ID of the agreement
     */
    function getAgreementPayment(bytes32 _agreementId) 
        external 
        view 
        returns (uint256) 
    {
        return agreementPayments[_agreementId];
    }

    /**
     * @dev Gets user's escrow balance
     * @param _user Address of the user
     */
    function getUserEscrowBalance(address _user) 
        external 
        view 
        returns (uint256) 
    {
        return userEscrowBalance[_user];
    }
}

