contracts/BountyIntegration.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "./AgentBounty.sol";
import "./AgentStaking.sol";
import "./PerformanceVerifier.sol";
import "./AIToken.sol";

/**
 * @title Bounty Integration Layer
 * @dev Bridges PerformanceVerifier with bounty and staking contracts
 * @notice Handles automatic bounty completion detection and cross-contract event handling
 */
contract BountyIntegration is Ownable, ReentrancyGuard {

    // State variables
    AgentBounty public agentBounty;
    AgentStaking public agentStaking;
    PerformanceVerifier public performanceVerifier;
    AIToken public aitbcToken;

    uint256 public integrationCounter;
    uint256 public autoVerificationThreshold = 90; // 90% accuracy for auto-verification
    uint256 public batchProcessingLimit = 50;
    uint256 public gasOptimizationThreshold = 100000;

    // Integration status
    enum IntegrationStatus { PENDING, PROCESSING, COMPLETED, FAILED }

    // Performance to bounty mapping
    struct PerformanceMapping {
        uint256 mappingId;
        bytes32 performanceHash;
        uint256 bountyId;
        uint256 submissionId;
        IntegrationStatus status;
        uint256 createdAt;
        uint256 processedAt;
        string errorMessage;
    }

    // Batch processing
    struct BatchRequest {
        uint256 batchId;
        uint256[] bountyIds;
        uint256[] submissionIds;
        bytes32[] performanceHashes;
        uint256[] accuracies;
        uint256[] responseTimes;
        IntegrationStatus status;
        uint256 createdAt;
        uint256 processedAt;
        uint256 successCount;
        uint256 failureCount;
    }

    // Event handlers
    struct EventHandler {
        bytes32 eventType;
        address targetContract;
        bytes4 functionSelector;
        bool isActive;
        uint256 priority;
    }

    // Mappings
    mapping(uint256 => PerformanceMapping) public performanceMappings;
    mapping(bytes32 => uint256) public performanceHashToMapping;
    mapping(uint256 => BatchRequest) public batchRequests;
    mapping(bytes32 => EventHandler) public eventHandlers;
    mapping(address => bool) public authorizedIntegrators;

    // Arrays
    uint256[] public pendingMappings;
    bytes32[] public performanceHashes;
    address[] public authorizedIntegratorList;

    // Events
    event PerformanceMapped(
        uint256 indexed mappingId,
        bytes32 indexed performanceHash,
        uint256 indexed bountyId,
        uint256 submissionId
    );

    event BountyAutoCompleted(
        uint256 indexed bountyId,
        uint256 indexed submissionId,
        address indexed submitter,
        uint256 rewardAmount
    );

    event StakingRewardsTriggered(
        address indexed agentWallet,
        uint256 totalEarnings,
        uint256 stakerCount
    );

    event BatchProcessed(
        uint256 indexed batchId,
        uint256 successCount,
        uint256 failureCount,
        uint256 gasUsed
    );

    event IntegrationFailed(
        uint256 indexed mappingId,
        string errorMessage,
        bytes32 indexed performanceHash
    );

    event EventHandlerRegistered(
        bytes32 indexed eventType,
        address indexed targetContract,
        bytes4 functionSelector
    );

    // Modifiers
    modifier mappingExists(uint256 _mappingId) {
        require(_mappingId < integrationCounter, "Mapping does not exist");
        _;
    }

    modifier onlyAuthorizedIntegrator() {
        require(authorizedIntegrators[msg.sender], "Not authorized integrator");
        _;
    }

    modifier validPerformanceHash(bytes32 _performanceHash) {
        require(_performanceHash != bytes32(0), "Invalid performance hash");
        _;
    }

    constructor(
        address _agentBounty,
        address _agentStaking,
        address _performanceVerifier,
        address _aitbcToken
    ) {
        agentBounty = AgentBounty(_agentBounty);
        agentStaking = AgentStaking(_agentStaking);
        performanceVerifier = PerformanceVerifier(_performanceVerifier);
        aitbcToken = AIToken(_aitbcToken);

        // Register default event handlers
        _registerEventHandler(
            keccak256("BOUNTY_COMPLETED"),
            _agentStaking,
            AgentStaking.distributeAgentEarnings.selector
        );

        _registerEventHandler(
            keccak256("PERFORMANCE_VERIFIED"),
            _agentBounty,
            AgentBounty.verifySubmission.selector
        );
    }

    /**
     * @dev Maps performance verification to bounty completion
     * @param _performanceHash Hash of performance metrics
     * @param _bountyId Bounty ID
     * @param _submissionId Submission ID
     */
    function mapPerformanceToBounty(
        bytes32 _performanceHash,
        uint256 _bountyId,
        uint256 _submissionId
    ) external 
        onlyAuthorizedIntegrator
        validPerformanceHash(_performanceHash)
        nonReentrant 
        returns (uint256) 
    {
        require(performanceHashToMapping[_performanceHash] == 0, "Performance already mapped");

        uint256 mappingId = integrationCounter++;

        PerformanceMapping storage perfMap = performanceMappings[mappingId];
        perfMap.mappingId = mappingId;
        perfMap.performanceHash = _performanceHash;
        perfMap.bountyId = _bountyId;
        perfMap.submissionId = _submissionId;
        perfMap.status = IntegrationStatus.PENDING;
        perfMap.createdAt = block.timestamp;

        performanceHashToMapping[_performanceHash] = mappingId;
        pendingMappings.push(mappingId);
        performanceHashes.push(_performanceHash);

        emit PerformanceMapped(mappingId, _performanceHash, _bountyId, _submissionId);

        // Attempt auto-processing
        _processMapping(mappingId);

        return mappingId;
    }

    /**
     * @dev Processes a single performance mapping
     * @param _mappingId Mapping ID
     */
    function processMapping(uint256 _mappingId) external 
        onlyAuthorizedIntegrator
        mappingExists(_mappingId)
        nonReentrant 
    {
        _processMapping(_mappingId);
    }

    /**
     * @dev Processes multiple mappings in a batch
     * @param _mappingIds Array of mapping IDs
     */
    function processBatchMappings(uint256[] calldata _mappingIds) external 
        onlyAuthorizedIntegrator
        nonReentrant 
    {
        require(_mappingIds.length <= batchProcessingLimit, "Batch too large");

        uint256 batchId = integrationCounter++;
        BatchRequest storage batch = batchRequests[batchId];
        batch.batchId = batchId;
        batch.bountyIds = new uint256[](_mappingIds.length);
        batch.submissionIds = new uint256[](_mappingIds.length);
        batch.performanceHashes = new bytes32[](_mappingIds.length);
        batch.accuracies = new uint256[](_mappingIds.length);
        batch.responseTimes = new uint256[](_mappingIds.length);
        batch.status = IntegrationStatus.PROCESSING;
        batch.createdAt = block.timestamp;

        uint256 gasStart = gasleft();
        uint256 successCount = 0;
        uint256 failureCount = 0;

        for (uint256 i = 0; i < _mappingIds.length; i++) {
            try this._processMappingInternal(_mappingIds[i]) {
                successCount++;
            } catch {
                failureCount++;
            }
        }

        batch.successCount = successCount;
        batch.failureCount = failureCount;
        batch.processedAt = block.timestamp;
        batch.status = IntegrationStatus.COMPLETED;

        uint256 gasUsed = gasStart - gasleft();

        emit BatchProcessed(batchId, successCount, failureCount, gasUsed);
    }

    /**
     * @dev Auto-verifies bounty submissions based on performance metrics
     * @param _bountyId Bounty ID
     * @param _submissionId Submission ID
     * @param _accuracy Achieved accuracy
     * @param _responseTime Response time
     */
    function autoVerifyBountySubmission(
        uint256 _bountyId,
        uint256 _submissionId,
        uint256 _accuracy,
        uint256 _responseTime
    ) external 
        onlyAuthorizedIntegrator
        nonReentrant 
    {
        // Get bounty details
        (,,,,,, bytes32 performanceCriteria, uint256 minAccuracy,,,,,) = agentBounty.getBounty(_bountyId);

        // Check if auto-verification conditions are met
        if (_accuracy >= autoVerificationThreshold && _accuracy >= minAccuracy) {
            // Verify the submission
            agentBounty.verifySubmission(_bountyId, _submissionId, true, address(this));

            // Get submission details to calculate rewards
            (uint256 bountyId, address submitter, bytes32 performanceHash, uint256 accuracy, uint256 responseTime,,,) = agentBounty.getSubmission(_submissionId);

            // Trigger staking rewards if applicable
            _triggerStakingRewards(submitter, _accuracy);

            emit BountyAutoCompleted(_bountyId, _submissionId, submitter, 0); // Reward amount will be set by bounty contract
        }
    }

    /**
     * @dev Handles performance verification events
     * @param _verificationId Performance verification ID
     * @param _accuracy Accuracy achieved
     * @param _responseTime Response time
     * @param _performanceHash Hash of performance metrics
     */
    function handlePerformanceVerified(
        uint256 _verificationId,
        uint256 _accuracy,
        uint256 _responseTime,
        bytes32 _performanceHash
    ) external 
        onlyAuthorizedIntegrator
        nonReentrant 
    {
        // Check if this performance is mapped to any bounties
        uint256 mappingId = performanceHashToMapping[_performanceHash];
        if (mappingId > 0) {
            PerformanceMapping storage perfMap = performanceMappings[mappingId];

            // Update agent staking metrics
            (uint256 bountyId, address submitter, bytes32 performanceHash, uint256 accuracy, uint256 responseTime,,,) = agentBounty.getSubmission(perfMap.submissionId);
            agentStaking.updateAgentPerformance(submitter, _accuracy, _accuracy >= autoVerificationThreshold);

            // Auto-verify bounty if conditions are met
            _autoVerifyBounty(perfMap.bountyId, perfMap.submissionId, _accuracy, _responseTime);
        }
    }

    /**
     * @dev Registers an event handler for cross-contract communication
     * @param _eventType Event type identifier
     * @param _targetContract Target contract address
     * @param _functionSelector Function selector to call
     */
    function registerEventHandler(
        bytes32 _eventType,
        address _targetContract,
        bytes4 _functionSelector
    ) external onlyOwner {
        require(_targetContract != address(0), "Invalid target contract");
        require(_functionSelector != bytes4(0), "Invalid function selector");

        eventHandlers[_eventType] = EventHandler({
            eventType: _eventType,
            targetContract: _targetContract,
            functionSelector: _functionSelector,
            isActive: true,
            priority: 0
        });

        emit EventHandlerRegistered(_eventType, _targetContract, _functionSelector);
    }

    /**
     * @dev Authorizes an integrator address
     * @param _integrator Address to authorize
     */
    function authorizeIntegrator(address _integrator) external onlyOwner {
        require(_integrator != address(0), "Invalid integrator address");
        require(!authorizedIntegrators[_integrator], "Already authorized");

        authorizedIntegrators[_integrator] = true;
        authorizedIntegratorList.push(_integrator);
    }

    /**
     * @dev Revokes integrator authorization
     * @param _integrator Address to revoke
     */
    function revokeIntegrator(address _integrator) external onlyOwner {
        require(authorizedIntegrators[_integrator], "Not authorized");

        authorizedIntegrators[_integrator] = false;

        // Remove from list
        for (uint256 i = 0; i < authorizedIntegratorList.length; i++) {
            if (authorizedIntegratorList[i] == _integrator) {
                authorizedIntegratorList[i] = authorizedIntegratorList[authorizedIntegratorList.length - 1];
                authorizedIntegratorList.pop();
                break;
            }
        }
    }

    /**
     * @dev Updates configuration parameters
     * @param _autoVerificationThreshold New auto-verification threshold
     * @param _batchProcessingLimit New batch processing limit
     * @param _gasOptimizationThreshold New gas optimization threshold
     */
    function updateConfiguration(
        uint256 _autoVerificationThreshold,
        uint256 _batchProcessingLimit,
        uint256 _gasOptimizationThreshold
    ) external onlyOwner {
        require(_autoVerificationThreshold <= 100, "Invalid threshold");
        require(_batchProcessingLimit <= 100, "Batch limit too high");

        autoVerificationThreshold = _autoVerificationThreshold;
        batchProcessingLimit = _batchProcessingLimit;
        gasOptimizationThreshold = _gasOptimizationThreshold;
    }

    // View functions

    /**
     * @dev Gets performance mapping details
     * @param _mappingId Mapping ID
     */
    function getPerformanceMapping(uint256 _mappingId) external view mappingExists(_mappingId) returns (
        bytes32 performanceHash,
        uint256 bountyId,
        uint256 submissionId,
        IntegrationStatus status,
        uint256 createdAt,
        uint256 processedAt,
        string memory errorMessage
    ) {
        PerformanceMapping storage perfMap = performanceMappings[_mappingId];
        return (
            perfMap.performanceHash,
            perfMap.bountyId,
            perfMap.submissionId,
            perfMap.status,
            perfMap.createdAt,
            perfMap.processedAt,
            perfMap.errorMessage
        );
    }

    /**
     * @dev Gets batch request details
     * @param _batchId Batch ID
     */
    function getBatchRequest(uint256 _batchId) external view returns (
        uint256[] memory bountyIds,
        uint256[] memory submissionIds,
        IntegrationStatus status,
        uint256 createdAt,
        uint256 processedAt,
        uint256 successCount,
        uint256 failureCount
    ) {
        BatchRequest storage batch = batchRequests[_batchId];
        return (
            batch.bountyIds,
            batch.submissionIds,
            batch.status,
            batch.createdAt,
            batch.processedAt,
            batch.successCount,
            batch.failureCount
        );
    }

    /**
     * @dev Gets pending mappings
     */
    function getPendingMappings() external view returns (uint256[] memory) {
        return pendingMappings;
    }

    /**
     * @dev Gets all performance hashes
     */
    function getPerformanceHashes() external view returns (bytes32[] memory) {
        return performanceHashes;
    }

    /**
     * @dev Gets authorized integrators
     */
    function getAuthorizedIntegrators() external view returns (address[] memory) {
        return authorizedIntegratorList;
    }

    /**
     * @dev Checks if an address is authorized
     * @param _integrator Address to check
     */
    function isAuthorizedIntegrator(address _integrator) external view returns (bool) {
        return authorizedIntegrators[_integrator];
    }

    /**
     * @dev Gets integration statistics
     */
    function getIntegrationStats() external view returns (
        uint256 totalMappings,
        uint256 pendingCount,
        uint256 completedCount,
        uint256 failedCount,
        uint256 averageProcessingTime
    ) {
        uint256 completed = 0;
        uint256 failed = 0;
        uint256 totalTime = 0;
        uint256 processedCount = 0;

        for (uint256 i = 0; i < integrationCounter; i++) {
            PerformanceMapping storage perfMap = performanceMappings[i];
            if (perfMap.status == IntegrationStatus.COMPLETED) {
                completed++;
                totalTime += perfMap.processedAt - perfMap.createdAt;
                processedCount++;
            } else if (perfMap.status == IntegrationStatus.FAILED) {
                failed++;
            }
        }

        uint256 avgTime = processedCount > 0 ? totalTime / processedCount : 0;

        return (
            integrationCounter,
            pendingMappings.length,
            completed,
            failed,
            avgTime
        );
    }

    // Internal functions

    function _processMapping(uint256 _mappingId) internal {
        PerformanceMapping storage perfMap = performanceMappings[_mappingId];

        if (perfMap.status != IntegrationStatus.PENDING) {
            return;
        }

        try this._processMappingInternal(_mappingId) {
            perfMap.status = IntegrationStatus.COMPLETED;
            perfMap.processedAt = block.timestamp;
        } catch Error(string memory reason) {
            perfMap.status = IntegrationStatus.FAILED;
            perfMap.errorMessage = reason;
            perfMap.processedAt = block.timestamp;

            emit IntegrationFailed(_mappingId, reason, perfMap.performanceHash);
        } catch {
            perfMap.status = IntegrationStatus.FAILED;
            perfMap.errorMessage = "Unknown error";
            perfMap.processedAt = block.timestamp;

            emit IntegrationFailed(_mappingId, "Unknown error", perfMap.performanceHash);
        }

        // Remove from pending
        _removeFromPending(_mappingId);
    }

    function _processMappingInternal(uint256 _mappingId) external {
        PerformanceMapping storage perfMap = performanceMappings[_mappingId];

        // Get bounty details
        (,,,,,, bytes32 performanceCriteria, uint256 minAccuracy,,,,,) = agentBounty.getBounty(perfMap.bountyId);

        // Get submission details
        (uint256 bountyId, address submitter, bytes32 performanceHash, uint256 accuracy, uint256 responseTime,,,) = agentBounty.getSubmission(perfMap.submissionId);

        // Verify performance criteria match
        require(perfMap.performanceHash == performanceHash, "Performance hash mismatch");

        // Check if accuracy meets requirements
        require(accuracy >= minAccuracy, "Accuracy below minimum");

        // Auto-verify if conditions are met
        if (accuracy >= autoVerificationThreshold) {
            agentBounty.verifySubmission(perfMap.bountyId, perfMap.submissionId, true, address(this));

            // Update agent staking metrics
            agentStaking.updateAgentPerformance(submitter, accuracy, true);

            // Trigger staking rewards
            _triggerStakingRewards(submitter, accuracy);
        }
    }

    function _autoVerifyBounty(
        uint256 _bountyId,
        uint256 _submissionId,
        uint256 _accuracy,
        uint256 _responseTime
    ) internal {
        if (_accuracy >= autoVerificationThreshold) {
            agentBounty.verifySubmission(_bountyId, _submissionId, true, address(this));
        }
    }

    function _triggerStakingRewards(address _agentWallet, uint256 _accuracy) internal {
        // Calculate earnings based on accuracy
        uint256 baseEarnings = (_accuracy * 100) * 10**18; // Simplified calculation

        // Distribute to stakers
        try agentStaking.distributeAgentEarnings(_agentWallet, baseEarnings) {
            emit StakingRewardsTriggered(_agentWallet, baseEarnings, 0);
        } catch {
            // Handle staking distribution failure
        }
    }

    function _registerEventHandler(
        bytes32 _eventType,
        address _targetContract,
        bytes4 _functionSelector
    ) internal {
        eventHandlers[_eventType] = EventHandler({
            eventType: _eventType,
            targetContract: _targetContract,
            functionSelector: _functionSelector,
            isActive: true,
            priority: 0
        });
    }

    function _removeFromPending(uint256 _mappingId) internal {
        for (uint256 i = 0; i < pendingMappings.length; i++) {
            if (pendingMappings[i] == _mappingId) {
                pendingMappings[i] = pendingMappings[pendingMappings.length - 1];
                pendingMappings.pop();
                break;
            }
        }
    }
}

contracts/ContractRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "../interfaces/IModularContracts.sol";

/**
 * @title ContractRegistry
 * @dev Central registry for all modular puzzle pieces
 * @notice Enables seamless inter-contract communication and supports upgrades
 */
contract ContractRegistry is IContractRegistry, Ownable, ReentrancyGuard, Pausable {

    // State variables
    uint256 public version = 1;
    mapping(bytes32 => address) public contractAddresses;
    mapping(bytes32 => uint256) public contractVersions;
    mapping(address => bytes32) public addressToId;
    bytes32[] public contractIds;

    // Events
    event ContractRegistered(bytes32 indexed contractId, address indexed contractAddress, uint256 version);
    event ContractUpdated(bytes32 indexed contractId, address indexed oldAddress, address indexed newAddress);
    event ContractDeregistered(bytes32 indexed contractId, address indexed contractAddress);
    event RegistryPaused(address indexed pausedBy);
    event RegistryUnpaused(address indexed unpausedBy);

    // Errors
    error ContractAlreadyRegistered(bytes32 contractId);
    error ContractNotFound(bytes32 contractId);
    error InvalidAddress(address contractAddress);
    error RegistryPausedError();
    error NotAuthorized();

    modifier whenNotPausedRegistry() {
        if (paused()) revert RegistryPausedError();
        _;
    }

    modifier validAddress(address contractAddress) {
        if (contractAddress == address(0)) revert InvalidAddress(contractAddress);
        _;
    }

    modifier onlyAuthorized() {
        if (msg.sender != owner() && !isContract(msg.sender)) revert NotAuthorized();
        _;
    }

    constructor() {
        // Register the registry itself
        bytes32 registryId = keccak256(abi.encodePacked("ContractRegistry"));
        contractAddresses[registryId] = address(this);
        contractVersions[registryId] = version;
        addressToId[address(this)] = registryId;
        contractIds.push(registryId);

        emit ContractRegistered(registryId, address(this), version);
    }

    /**
     * @dev Initialize the registry (implements IModularContract)
     */
    function initialize(address /*registry*/) external pure override {
        // Registry doesn't need external initialization
        revert("Self-initialization not allowed");
    }

    /**
     * @dev Upgrade the registry version
     */
    function upgrade(address /*newImplementation*/) external override onlyOwner {
        version++;
        emit ContractUpdated(keccak256(abi.encodePacked("ContractRegistry")), address(this), address(this));
    }

    /**
     * @dev Pause the registry
     */
    function pause() external override onlyOwner {
        _pause();
        emit RegistryPaused(msg.sender);
    }

    /**
     * @dev Unpause the registry
     */
    function unpause() external override onlyOwner {
        _unpause();
        emit RegistryUnpaused(msg.sender);
    }

    /**
     * @dev Get the current version
     */
    function getVersion() external view override returns (uint256) {
        return version;
    }

    /**
     * @dev Register a new contract
     */
    function registerContract(bytes32 contractId, address contractAddress) 
        external 
        override 
        onlyAuthorized 
        whenNotPausedRegistry 
        validAddress(contractAddress)
        nonReentrant 
    {
        if (contractAddresses[contractId] != address(0)) {
            revert ContractAlreadyRegistered(contractId);
        }

        contractAddresses[contractId] = contractAddress;
        contractVersions[contractId] = 1;
        addressToId[contractAddress] = contractId;
        contractIds.push(contractId);

        emit ContractRegistered(contractId, contractAddress, 1);
    }

    /**
     * @dev Get a contract address by ID
     */
    function getContract(bytes32 contractId) external view override returns (address) {
        address contractAddress = contractAddresses[contractId];
        if (contractAddress == address(0)) {
            revert ContractNotFound(contractId);
        }
        return contractAddress;
    }

    /**
     * @dev Update an existing contract address
     */
    function updateContract(bytes32 contractId, address newAddress) 
        external 
        override 
        onlyAuthorized 
        whenNotPausedRegistry 
        validAddress(newAddress)
        nonReentrant 
    {
        address oldAddress = contractAddresses[contractId];
        if (oldAddress == address(0)) {
            revert ContractNotFound(contractId);
        }

        contractAddresses[contractId] = newAddress;
        contractVersions[contractId]++;
        delete addressToId[oldAddress];
        addressToId[newAddress] = contractId;

        emit ContractUpdated(contractId, oldAddress, newAddress);
    }

    /**
     * @dev Deregister a contract
     */
    function deregisterContract(bytes32 contractId) external onlyAuthorized whenNotPausedRegistry nonReentrant {
        address contractAddress = contractAddresses[contractId];
        if (contractAddress == address(0)) {
            revert ContractNotFound(contractId);
        }

        delete contractAddresses[contractId];
        delete contractVersions[contractId];
        delete addressToId[contractAddress];

        // Remove from contractIds array
        for (uint256 i = 0; i < contractIds.length; i++) {
            if (contractIds[i] == contractId) {
                contractIds[i] = contractIds[contractIds.length - 1];
                contractIds.pop();
                break;
            }
        }

        emit ContractDeregistered(contractId, contractAddress);
    }

    /**
     * @dev List all registered contracts
     */
    function listContracts() external view override returns (bytes32[] memory, address[] memory) {
        bytes32[] memory ids = new bytes32[](contractIds.length);
        address[] memory addresses = new address[](contractIds.length);

        for (uint256 i = 0; i < contractIds.length; i++) {
            ids[i] = contractIds[i];
            addresses[i] = contractAddresses[contractIds[i]];
        }

        return (ids, addresses);
    }

    /**
     * @dev Get contract version
     */
    function getContractVersion(bytes32 contractId) external view returns (uint256) {
        return contractVersions[contractId];
    }

    /**
     * @dev Check if an address is a registered contract
     */
    function isRegisteredContract(address contractAddress) external view returns (bool) {
        bytes32 contractId = addressToId[contractAddress];
        return contractAddresses[contractId] != address(0);
    }

    /**
     * @dev Get contract ID by address
     */
    function getContractId(address contractAddress) external view returns (bytes32) {
        return addressToId[contractAddress];
    }

    /**
     * @dev Batch register contracts
     */
    function batchRegisterContracts(bytes32[] memory _contractIds, address[] memory _contractAddresses) 
        external 
        onlyAuthorized 
        whenNotPausedRegistry
    {
        require(_contractIds.length == _contractAddresses.length, "Array length mismatch");

        for (uint256 i = 0; i < _contractIds.length; i++) {
            if (_contractAddresses[i] != address(0) && contractAddresses[_contractIds[i]] == address(0)) {
                contractAddresses[_contractIds[i]] = _contractAddresses[i];
                contractVersions[_contractIds[i]] = 1;
                addressToId[_contractAddresses[i]] = _contractIds[i];

                emit ContractRegistered(_contractIds[i], _contractAddresses[i], 1);
            }
        }
    }

    /**
     * @dev Check if address is a contract
     */
    function isContract(address addr) internal view returns (bool) {
        uint256 size;
        assembly {
            size := extcodesize(addr)
        }
        return size > 0;
    }

    /**
     * @dev Get registry statistics
     */
    function getRegistryStats() external view returns (
        uint256 totalContracts,
        uint256 totalVersion,
        bool isPaused,
        address owner
    ) {
        return (
            contractIds.length,
            version,
            paused(),
            this.owner()
        );
    }
}

contracts/CrossChainAtomicSwap.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title CrossChainAtomicSwap
 * @dev Hashed Time-Locked Contract (HTLC) for trustless cross-chain swaps.
 */
contract CrossChainAtomicSwap is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    enum SwapStatus {
        INVALID,
        OPEN,
        COMPLETED,
        REFUNDED
    }

    struct Swap {
        address initiator;
        address participant;
        address token; // address(0) for native currency
        uint256 amount;
        bytes32 hashlock;
        uint256 timelock;
        SwapStatus status;
    }

    mapping(bytes32 => Swap) public swaps; // swapId => Swap mapping

    event SwapInitiated(
        bytes32 indexed swapId,
        address indexed initiator,
        address indexed participant,
        address token,
        uint256 amount,
        bytes32 hashlock,
        uint256 timelock
    );

    event SwapCompleted(
        bytes32 indexed swapId,
        address indexed participant,
        bytes32 secret
    );

    event SwapRefunded(
        bytes32 indexed swapId,
        address indexed initiator
    );

    /**
     * @dev Initiate an atomic swap. The amount is locked in this contract.
     */
    function initiateSwap(
        bytes32 _swapId,
        address _participant,
        address _token,
        uint256 _amount,
        bytes32 _hashlock,
        uint256 _timelock
    ) external payable nonReentrant {
        require(swaps[_swapId].status == SwapStatus.INVALID, "Swap ID already exists");
        require(_participant != address(0), "Invalid participant");
        require(_timelock > block.timestamp, "Timelock must be in the future");
        require(_amount > 0, "Amount must be > 0");

        if (_token == address(0)) {
            require(msg.value == _amount, "Incorrect ETH amount sent");
        } else {
            require(msg.value == 0, "ETH sent but ERC20 token specified");
            IERC20(_token).safeTransferFrom(msg.sender, address(this), _amount);
        }

        swaps[_swapId] = Swap({
            initiator: msg.sender,
            participant: _participant,
            token: _token,
            amount: _amount,
            hashlock: _hashlock,
            timelock: _timelock,
            status: SwapStatus.OPEN
        });

        emit SwapInitiated(
            _swapId,
            msg.sender,
            _participant,
            _token,
            _amount,
            _hashlock,
            _timelock
        );
    }

    /**
     * @dev Complete the swap by providing the secret that hashes to the hashlock.
     */
    function completeSwap(bytes32 _swapId, bytes32 _secret) external nonReentrant {
        Swap storage swap = swaps[_swapId];

        require(swap.status == SwapStatus.OPEN, "Swap is not open");
        require(block.timestamp < swap.timelock, "Swap timelock expired");
        require(
            sha256(abi.encodePacked(_secret)) == swap.hashlock,
            "Invalid secret"
        );

        swap.status = SwapStatus.COMPLETED;

        if (swap.token == address(0)) {
            (bool success, ) = payable(swap.participant).call{value: swap.amount}("");
            require(success, "ETH transfer failed");
        } else {
            IERC20(swap.token).safeTransfer(swap.participant, swap.amount);
        }

        emit SwapCompleted(_swapId, swap.participant, _secret);
    }

    /**
     * @dev Refund the swap if the timelock has expired and it wasn't completed.
     */
    function refundSwap(bytes32 _swapId) external nonReentrant {
        Swap storage swap = swaps[_swapId];

        require(swap.status == SwapStatus.OPEN, "Swap is not open");
        require(block.timestamp >= swap.timelock, "Swap timelock not yet expired");

        swap.status = SwapStatus.REFUNDED;

        if (swap.token == address(0)) {
            (bool success, ) = payable(swap.initiator).call{value: swap.amount}("");
            require(success, "ETH transfer failed");
        } else {
            IERC20(swap.token).safeTransfer(swap.initiator, swap.amount);
        }

        emit SwapRefunded(_swapId, swap.initiator);
    }
}

contracts/CrossChainBridge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/security/Pausable.sol";
import "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import "@openzeppelin/contracts/utils/cryptography/MerkleProof.sol";

/**
 * @title CrossChainBridge
 * @dev Secure cross-chain asset transfer protocol with ZK proof validation
 * @notice Enables bridging of assets between different blockchain networks
 */
contract CrossChainBridge is Ownable, ReentrancyGuard, Pausable {
    using SafeERC20 for IERC20;
    using ECDSA for bytes32;

    // Constants
    uint256 public constant BRIDGE_FEE_PERCENTAGE = 50; // 0.5% bridge fee
    uint256 public constant BASIS_POINTS = 10000;
    uint256 public constant MAX_FEE = 500; // Maximum 5% fee
    uint256 public constant MIN_CONFIRMATIONS = 3;
    uint256 public constant BRIDGE_TIMEOUT = 24 hours;
    uint256 public constant MAX_BRIDGE_AMOUNT = 1000000 * 1e18; // Max 1M tokens per bridge

    // Enums
    enum BridgeStatus { PENDING, CONFIRMED, COMPLETED, FAILED, CANCELLED }
    enum ChainType { ETHEREUM, POLYGON, BSC, ARBITRUM, OPTIMISM, AVALANCHE }

    // Structs
    struct BridgeRequest {
        uint256 requestId;
        address sourceToken;
        address targetToken;
        uint256 amount;
        uint256 sourceChainId;
        uint256 targetChainId;
        address recipient;
        address sender;
        uint256 fee;
        bytes32 lockTxHash;
        bytes32 unlockTxHash;
        BridgeStatus status;
        uint256 createdAt;
        uint256 confirmedAt;
        uint256 completedAt;
        uint256 confirmations;
        mapping(address => bool) hasConfirmed;
    }

    struct SupportedToken {
        address tokenAddress;
        bool isActive;
        uint256 bridgeLimit;
        uint256 feePercentage;
        bool requiresWhitelist;
    }

    struct ChainConfig {
        uint256 chainId;
        ChainType chainType;
        string name;
        bool isActive;
        address bridgeContract;
        uint256 minConfirmations;
        uint256 avgBlockTime;
    }

    struct Validator {
        address validatorAddress;
        bool isActive;
        uint256 weight;
        uint256 lastValidation;
        uint256 totalValidations;
    }

    // State variables
    uint256 public requestCounter;
    uint256 public totalBridgedAmount;
    uint256 public totalFeesCollected;
    address public feeRecipient;
    bytes32 public merkleRoot;

    // Mappings
    mapping(uint256 => BridgeRequest) public bridgeRequests;
    mapping(address => SupportedToken) public supportedTokens;
    mapping(uint256 => ChainConfig) public supportedChains;
    mapping(address => Validator) public validators;
    mapping(uint256 => address[]) public chainValidators;
    mapping(bytes32 => bool) public processedTxHashes;
    mapping(address => uint256[]) public userBridgeHistory;

    // Arrays
    address[] public activeValidators;
    uint256[] public supportedChainIds;
    address[] public supportedTokenAddresses;

    // Events
    event BridgeInitiated(
        uint256 indexed requestId,
        address indexed sender,
        address indexed recipient,
        address sourceToken,
        uint256 amount,
        uint256 sourceChainId,
        uint256 targetChainId
    );
    event BridgeConfirmed(uint256 indexed requestId, address indexed validator, bytes32 lockTxHash);
    event BridgeCompleted(uint256 indexed requestId, bytes32 unlockTxHash);
    event BridgeFailed(uint256 indexed requestId, string reason);
    event BridgeCancelled(uint256 indexed requestId);
    event ValidatorAdded(address indexed validator, uint256 weight);
    event ValidatorRemoved(address indexed validator);
    event TokenSupported(address indexed token, uint256 bridgeLimit, uint256 fee);
    event ChainSupported(uint256 indexed chainId, string name, ChainType chainType);

    // Modifiers
    modifier onlyActiveValidator() {
        require(validators[msg.sender].isActive, "Not an active validator");
        _;
    }

    modifier validRequest(uint256 requestId) {
        require(requestId > 0 && requestId <= requestCounter, "Invalid request ID");
        _;
    }

    modifier supportedToken(address token) {
        require(supportedTokens[token].isActive, "Token not supported");
        _;
    }

    modifier supportedChain(uint256 chainId) {
        require(supportedChains[chainId].isActive, "Chain not supported");
        _;
    }

    modifier withinBridgeLimit(address token, uint256 amount) {
        require(amount <= supportedTokens[token].bridgeLimit, "Amount exceeds bridge limit");
        _;
    }

    constructor(address _feeRecipient) {
        feeRecipient = _feeRecipient;

        // Initialize with Ethereum mainnet
        _addChain(1, ChainType.ETHEREUM, "Ethereum", true, address(0), 12, 12);
    }

    /**
     * @dev Initiates a cross-chain bridge transfer
     * @param sourceToken Address of the source token
     * @param targetToken Address of the target token
     * @param amount Amount to bridge
     * @param targetChainId Target chain ID
     * @param recipient Recipient address on target chain
     * @return requestId The bridge request ID
     */
    function initiateBridge(
        address sourceToken,
        address targetToken,
        uint256 amount,
        uint256 targetChainId,
        address recipient
    ) 
        external 
        nonReentrant 
        whenNotPaused
        supportedToken(sourceToken)
        supportedChain(targetChainId)
        withinBridgeLimit(sourceToken, amount)
        returns (uint256 requestId) 
    {
        require(sourceToken != address(0), "Invalid source token");
        require(targetToken != address(0), "Invalid target token");
        require(recipient != address(0), "Invalid recipient");
        require(amount > 0, "Amount must be greater than 0");
        require(targetChainId != block.chainid, "Same chain bridging not allowed");

        // Calculate bridge fee
        uint256 fee = (amount * supportedTokens[sourceToken].feePercentage) / BASIS_POINTS;
        uint256 totalAmount = amount + fee;

        // Transfer tokens to contract
        IERC20(sourceToken).safeTransferFrom(msg.sender, address(this), totalAmount);

        // Create bridge request
        requestCounter++;
        requestId = requestCounter;

        BridgeRequest storage request = bridgeRequests[requestId];
        request.requestId = requestId;
        request.sourceToken = sourceToken;
        request.targetToken = targetToken;
        request.amount = amount;
        request.sourceChainId = block.chainid;
        request.targetChainId = targetChainId;
        request.recipient = recipient;
        request.sender = msg.sender;
        request.fee = fee;
        request.status = BridgeStatus.PENDING;
        request.createdAt = block.timestamp;

        // Update statistics
        totalBridgedAmount += amount;
        totalFeesCollected += fee;
        userBridgeHistory[msg.sender].push(requestId);

        // Transfer fee to fee recipient
        if (fee > 0) {
            IERC20(sourceToken).safeTransfer(feeRecipient, fee);
        }

        emit BridgeInitiated(
            requestId,
            msg.sender,
            recipient,
            sourceToken,
            amount,
            block.chainid,
            targetChainId
        );

        return requestId;
    }

    /**
     * @dev Confirms a bridge request by a validator
     * @param requestId The bridge request ID
     * @param lockTxHash The transaction hash of the lock transaction
     * @param signature Validator signature
     */
    function confirmBridge(
        uint256 requestId,
        bytes32 lockTxHash,
        bytes memory signature
    ) 
        external 
        onlyActiveValidator
        validRequest(requestId)
    {
        BridgeRequest storage request = bridgeRequests[requestId];

        require(request.status == BridgeStatus.PENDING, "Request not pending");
        require(!request.hasConfirmed[msg.sender], "Already confirmed");
        require(block.timestamp <= request.createdAt + BRIDGE_TIMEOUT, "Bridge request expired");

        // Verify signature
        bytes32 messageHash = keccak256(abi.encodePacked(requestId, lockTxHash, block.chainid));
        require(_verifySignature(messageHash, signature, msg.sender), "Invalid signature");

        // Record confirmation
        request.hasConfirmed[msg.sender] = true;
        request.confirmations++;
        request.lockTxHash = lockTxHash;
        validators[msg.sender].lastValidation = block.timestamp;
        validators[msg.sender].totalValidations++;

        // Check if we have enough confirmations
        uint256 requiredConfirmations = _getRequiredConfirmations(request.sourceChainId);
        if (request.confirmations >= requiredConfirmations) {
            request.status = BridgeStatus.CONFIRMED;
            request.confirmedAt = block.timestamp;
        }

        emit BridgeConfirmed(requestId, msg.sender, lockTxHash);
    }

    /**
     * @dev Completes a bridge request on the target chain
     * @param requestId The bridge request ID
     * @param unlockTxHash The transaction hash of the unlock transaction
     * @param proof Merkle proof for verification
     */
    function completeBridge(
        uint256 requestId,
        bytes32 unlockTxHash,
        bytes32[] calldata proof
    ) 
        external 
        nonReentrant 
        whenNotPaused
        validRequest(requestId)
    {
        BridgeRequest storage request = bridgeRequests[requestId];

        require(request.status == BridgeStatus.CONFIRMED, "Request not confirmed");
        require(block.chainid == request.targetChainId, "Wrong chain");
        require(!processedTxHashes[unlockTxHash], "Transaction already processed");

        // Verify Merkle proof
        bytes32 leaf = keccak256(abi.encodePacked(requestId, request.recipient, request.amount));
        require(MerkleProof.verify(proof, merkleRoot, leaf), "Invalid Merkle proof");

        // Mark transaction as processed
        processedTxHashes[unlockTxHash] = true;
        request.unlockTxHash = unlockTxHash;
        request.status = BridgeStatus.COMPLETED;
        request.completedAt = block.timestamp;

        // Transfer tokens to recipient
        IERC20(request.targetToken).safeTransfer(request.recipient, request.amount);

        emit BridgeCompleted(requestId, unlockTxHash);
    }

    /**
     * @dev Cancels a bridge request
     * @param requestId The bridge request ID
     * @param reason Reason for cancellation
     */
    function cancelBridge(uint256 requestId, string memory reason) 
        external 
        nonReentrant 
        validRequest(requestId) 
    {
        BridgeRequest storage request = bridgeRequests[requestId];

        require(request.status == BridgeStatus.PENDING, "Request not pending");
        require(
            msg.sender == request.sender || msg.sender == owner(),
            "Not authorized to cancel"
        );
        require(block.timestamp > request.createdAt + BRIDGE_TIMEOUT, "Bridge not expired");

        // Refund tokens to sender
        uint256 refundAmount = request.amount + request.fee;
        IERC20(request.sourceToken).safeTransfer(request.sender, refundAmount);

        // Update status
        request.status = BridgeStatus.CANCELLED;

        emit BridgeCancelled(requestId);
        emit BridgeFailed(requestId, reason);
    }

    /**
     * @dev Gets bridge request details
     * @param requestId The bridge request ID
     * @return sourceChainId The source chain ID
     * @return targetChainId The destination chain ID
     * @return sourceToken The source token address
     * @return amount The amount to bridge
     * @return recipient The recipient address
     * @return status The request status
     * @return createdAt The request timestamp
     */
    function getBridgeRequest(uint256 requestId) 
        external 
        view 
        validRequest(requestId)
        returns (
            uint256 sourceChainId,
            uint256 targetChainId,
            address sourceToken,
            uint256 amount,
            address recipient,
            BridgeStatus status,
            uint256 createdAt
        ) 
    {
        BridgeRequest storage request = bridgeRequests[requestId];
        return (
            request.sourceChainId,
            request.targetChainId,
            request.sourceToken,
            request.amount,
            request.recipient,
            request.status,
            request.createdAt
        );
    }

    /**
     * @dev Gets user's bridge history
     * @param user The user address
     * @return requestIds Array of bridge request IDs
     */
    function getUserBridgeHistory(address user) 
        external 
        view 
        returns (uint256[] memory requestIds) 
    {
        return userBridgeHistory[user];
    }

    /**
     * @dev Validates a bridge request signature
     * @param requestId The bridge request ID
     * @param lockTxHash The lock transaction hash
     * @param signature The signature to validate
     * @return isValid Whether the signature is valid
     */
    function validateBridgeRequest(uint256 requestId, bytes32 lockTxHash, bytes memory signature) 
        external 
        view 
        returns (bool isValid) 
    {
        bytes32 messageHash = keccak256(abi.encodePacked(requestId, lockTxHash, block.chainid));
        address recoveredAddress = messageHash.recover(signature);
        return validators[recoveredAddress].isActive;
    }

    // Admin functions

    /**
     * @dev Adds support for a new token
     * @param tokenAddress The token address
     * @param bridgeLimit Maximum bridge amount
     * @param feePercentage Bridge fee percentage
     * @param requiresWhitelist Whether whitelist is required
     */
    function addSupportedToken(
        address tokenAddress,
        uint256 bridgeLimit,
        uint256 feePercentage,
        bool requiresWhitelist
    ) external onlyOwner {
        require(tokenAddress != address(0), "Invalid token address");
        require(feePercentage <= MAX_FEE, "Fee too high");

        supportedTokens[tokenAddress] = SupportedToken({
            tokenAddress: tokenAddress,
            isActive: true,
            bridgeLimit: bridgeLimit,
            feePercentage: feePercentage,
            requiresWhitelist: requiresWhitelist
        });

        supportedTokenAddresses.push(tokenAddress);
        emit TokenSupported(tokenAddress, bridgeLimit, feePercentage);
    }

    /**
     * @dev Adds support for a new blockchain
     * @param chainId The chain ID
     * @param chainType The chain type
     * @param name The chain name
     * @param bridgeContract The bridge contract address on that chain
     * @param minConfirmations Minimum confirmations required
     * @param avgBlockTime Average block time in seconds
     */
    function addSupportedChain(
        uint256 chainId,
        ChainType chainType,
        string memory name,
        address bridgeContract,
        uint256 minConfirmations,
        uint256 avgBlockTime
    ) external onlyOwner {
        require(chainId > 0, "Invalid chain ID");
        require(chainId != block.chainid, "Cannot add current chain");

        supportedChains[chainId] = ChainConfig({
            chainId: chainId,
            chainType: chainType,
            name: name,
            isActive: true,
            bridgeContract: bridgeContract,
            minConfirmations: minConfirmations,
            avgBlockTime: avgBlockTime
        });

        supportedChainIds.push(chainId);
        emit ChainSupported(chainId, name, chainType);
    }

    /**
     * @dev Adds a new validator
     * @param validatorAddress The validator address
     * @param weight The validator weight
     */
    function addValidator(address validatorAddress, uint256 weight) external onlyOwner {
        require(validatorAddress != address(0), "Invalid validator address");
        require(!validators[validatorAddress].isActive, "Validator already exists");

        validators[validatorAddress] = Validator({
            validatorAddress: validatorAddress,
            isActive: true,
            weight: weight,
            lastValidation: 0,
            totalValidations: 0
        });

        activeValidators.push(validatorAddress);
        emit ValidatorAdded(validatorAddress, weight);
    }

    /**
     * @dev Removes a validator
     * @param validatorAddress The validator address
     */
    function removeValidator(address validatorAddress) external onlyOwner {
        require(validators[validatorAddress].isActive, "Validator not active");

        validators[validatorAddress].isActive = false;

        // Remove from active validators array
        for (uint i = 0; i < activeValidators.length; i++) {
            if (activeValidators[i] == validatorAddress) {
                activeValidators[i] = activeValidators[activeValidators.length - 1];
                activeValidators.pop();
                break;
            }
        }

        emit ValidatorRemoved(validatorAddress);
    }

    /**
     * @dev Updates the Merkle root for transaction verification
     * @param newMerkleRoot The new Merkle root
     */
    function updateMerkleRoot(bytes32 newMerkleRoot) external onlyOwner {
        merkleRoot = newMerkleRoot;
    }

    /**
     * @dev Sets the fee recipient address
     * @param newFeeRecipient The new fee recipient
     */
    function setFeeRecipient(address newFeeRecipient) external onlyOwner {
        require(newFeeRecipient != address(0), "Invalid address");
        feeRecipient = newFeeRecipient;
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    // Internal functions

    function _verifySignature(
        bytes32 messageHash,
        bytes memory signature,
        address signer
    ) internal pure returns (bool) {
        bytes32 ethSignedMessageHash = keccak256(
            abi.encodePacked("\x19Ethereum Signed Message:\n32", messageHash)
        );
        return ethSignedMessageHash.recover(signature) == signer;
    }

    function _getRequiredConfirmations(uint256 chainId) internal view returns (uint256) {
        ChainConfig storage chain = supportedChains[chainId];
        return chain.minConfirmations > 0 ? chain.minConfirmations : MIN_CONFIRMATIONS;
    }

    function _addChain(
        uint256 chainId,
        ChainType chainType,
        string memory name,
        bool isActive,
        address bridgeContract,
        uint256 minConfirmations,
        uint256 avgBlockTime
    ) internal {
        supportedChains[chainId] = ChainConfig({
            chainId: chainId,
            chainType: chainType,
            name: name,
            isActive: isActive,
            bridgeContract: bridgeContract,
            minConfirmations: minConfirmations,
            avgBlockTime: avgBlockTime
        });

        supportedChainIds.push(chainId);
        emit ChainSupported(chainId, name, chainType);
    }

    // Emergency functions

    function emergencyWithdraw(address token, uint256 amount) external onlyOwner {
        IERC20(token).safeTransfer(owner(), amount);
    }

    function emergencyPause() external onlyOwner {
        _pause();
    }
}

